  const sphereGeo = new THREE.SphereGeometry(1, 24, 16);
  const stemGeo = new THREE.CylinderGeometry(0.004, 0.005, 0.022, 10);
  const leafGeo = new THREE.SphereGeometry(0.012, 12, 8);
  const bananaGeo = new THREE.TorusGeometry(0.034, 0.0125, 12, 20, Math.PI * 0.95);
  const tipGeo = new THREE.SphereGeometry(0.006, 10, 8);
  const discGeo = new THREE.CylinderGeometry(0.055, 0.055, 0.006, 24);

  // ---------- Basket ----------
  const basket = new THREE.Group();
  basket.name = 'Basket';
  basket.position.set(0, 0, -0.05);
  root.add(basket);

  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.07, 0.02, 24), basketBaseMat);
  base.position.y = 0.01;
  basket.add(base);

  const wall = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.078, 0.11, 24, 1, true), basketWallMat);
  wall.position.y = 0.075;
  basket.add(wall);

  const innerBottom = new THREE.Mesh(new THREE.CircleGeometry(0.078, 24), basketBaseMat);
  innerBottom.rotation.x = -Math.PI / 2;
  innerBottom.position.y = 0.0205;
  basket.add(innerBottom);

  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.11, 0.012, 12, 32), rimMat);
  rim.rotation.x = Math.PI / 2;
  rim.position.y = 0.13;
  basket.add(rim);

