  const arrow = new THREE.Mesh(new THREE.ConeGeometry(0.02, 0.035, 16), arrowMat);
  arrow.rotation.x = Math.PI;
  arrow.position.set(0, 0.29, -0.05);
  root.add(arrow);

  // ---------- Fruits ----------
  function makeApple() {
    const g = new THREE.Group();
    g.name = 'Apple';
    const body = new THREE.Mesh(sphereGeo, appleMat);
    body.scale.setScalar(0.035);
    g.add(body);
    const stem = new THREE.Mesh(stemGeo, stemMat);
    stem.position.y = 0.04;
    g.add(stem);
    const leaf = new THREE.Mesh(leafGeo, leafMat);
    leaf.scale.set(1.4, 0.5, 0.8);
    leaf.position.set(0.014, 0.045, 0);
    leaf.rotation.z = -0.4;
    g.add(leaf);
    return g;
  }
  function makeBanana() {
    const g = new THREE.Group();
    g.name = 'Banana';
    const body = new THREE.Mesh(bananaGeo, bananaMat);
    body.rotation.z = Math.PI * 0.05;
    body.rotation.y = Math.PI / 2;
    g.add(body);
    const t1 = new THREE.Mesh(tipGeo, bananaTipMat);
    t1.position.set(0.032, -0.018, 0);
    g.add(t1);
    const t2 = new THREE.Mesh(tipGeo, bananaTipMat);
    t2.position.set(-0.03, 0.022, 0);
    g.add(t2);
    return g;
  }
  function makeOrange() {
    const g = new THREE.Group();
    g.name = 'Orange';
    const body = new THREE.Mesh(sphereGeo, orangeMat);
    body.scale.setScalar(0.033);
    g.add(body);
    const dot = new THREE.Mesh(tipGeo, orangeDimpleMat);
    dot.position.y = 0.032;
    g.add(dot);
    return g;
  }

  const apple = makeApple();
  const banana = makeBanana();
  const orange = makeOrange();
  root.add(apple);
  root.add(banana);
  root.add(orange);

  traits(apple, { grab: true });
  traits(banana, { grab: true });
  traits(orange, { grab: true });

  // home + slot + rest heights
  const fruits = [
    { group: apple, price: 1.2, home: [-0.25, 0.041, 0.18], slot: [-0.045, 0.06, -0.05], restY: 0.035, inBasket: false, wasGrabbed: false, statusId: 'appleStatus' },
    { group: banana, price: 0.8, home: [0, 0.026, 0.21], slot: [0.045, 0.055, -0.05], restY: 0.02, inBasket: false, wasGrabbed: false, statusId: 'bananaStatus' },
    { group: orange, price: 1.5, home: [0.25, 0.039, 0.18], slot: [0, 0.115, -0.05], restY: 0.033, inBasket: false, wasGrabbed: false, statusId: 'orangeStatus' },
  ];
  for (const f of fruits) {
    f.group.position.set(f.home[0], f.home[1], f.home[2]);
  }
  // orient banana flat on table
  banana.rotation.set(0, 0.5, 0.15);

  // home mats
  const matMeshes = [];
  const matDefs = [
    { mat: matRed, x: -0.25, z: 0.18 },
    { mat: matYellow, x: 0, z: 0.21 },
    { mat: matOrange, x: 0.25, z: 0.18 },
  ];
  for (const d of matDefs) {
    const m = new THREE.Mesh(discGeo, d.mat);
    m.position.set(d.x, 0.003, d.z);
    root.add(m);
    matMeshes.push(m);
  }

  // ---------- UI panel ----------
  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 8px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: left; }
      .sub { color: #b9bfc9; font-size: 20px; text-align: left; }
      .row { display: flex; flex-direction: row; gap: 8px; align-items: center; justify-content: space-between; padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #2a2e35; }
      .left { display: flex; flex-direction: row; gap: 8px; align-items: center; }
      .dotR { color: #ff6b6b; font-size: 24px; font-weight: 700; }
      .dotY { color: #ffd54d; font-size: 24px; font-weight: 700; }
      .dotO { color: #ff9f2e; font-size: 24px; font-weight: 700; }
      .fname { color: #ffffff; font-size: 22px; font-weight: 700; }
      .fprice { color: #d7dbe2; font-size: 20px; }
      .status { color: #9aa0ab; font-size: 20px; font-weight: 700; }
      .totalBox { display: flex; flex-direction: row; gap: 8px; align-items: center; justify-content: space-between; padding-top: 12px; padding-bottom: 12px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #12331f; }
      .totalLabel { color: #b8e6c2; font-size: 22px; font-weight: 700; }
      .totalVal { color: #ffffff; font-size: 34px; font-weight: 700; }
      .count { color: #b8e6c2; font-size: 20px; text-align: left; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #3a3f48; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Fruit Basket</span>
      <span class="sub">Pinch a fruit, drop it in the basket</span>
      <div class="row"><div class="left"><span class="dotR">●</span><span class="fname">Apple</span><span class="fprice">$1.20</span></div><span class="status" id="appleStatus">On table</span></div>
      <div class="row"><div class="left"><span class="dotY">●</span><span class="fname">Banana</span><span class="fprice">$0.80</span></div><span class="status" id="bananaStatus">On table</span></div>
      <div class="row"><div class="left"><span class="dotO">●</span><span class="fname">Orange</span><span class="fprice">$1.50</span></div><span class="status" id="orangeStatus">On table</span></div>
      <div class="totalBox"><span class="totalLabel">Basket total</span><span class="totalVal" id="total">$0.00</span></div>
      <span class="count" id="count">0 of 3 fruits in basket</span>
      <button class="btn" id="reset"><span class="btn-text">Reset basket</span></button>
    </div>`, { width: 0.31, position: [0.30, 0.23, 0.0], rotationY: -0.35 });
  root.add(panel.object3D);

  function refreshPanel() {
    let total = 0;
    let n = 0;
    for (const f of fruits) {
      if (f.inBasket) { total += f.price; n += 1; }
    }
    const totalStr = '$' + total.toFixed(2);
    panel.set('total', { text: totalStr });
    let countStr = n + ' of 3 fruits in basket';
    if (n === 3) countStr = 'All 3 fruits in basket!';
    panel.set('count', { text: countStr });
    for (const f of fruits) {
      if (f.inBasket) panel.set(f.statusId, { text: 'In basket', color: '#7dff9b' });
      else panel.set(f.statusId, { text: 'On table', color: '#9aa0ab' });
    }
  }
  refreshPanel();

  panel.on('reset', 'click', () => {
    for (const f of fruits) {
      f.inBasket = false;
      f.wasGrabbed = false;
      f.group.position.set(f.home[0], f.home[1], f.home[2]);
    }
    banana.rotation.set(0, 0.5, 0.15);
    refreshPanel();
  });

  const basketX = 0;
  const basketZ = -0.05;
  let panelDirty = false;

  return {
    root,
    update(time, delta) {
      const d = Math.min(delta, 0.05);
      panelDirty = false;
      let hover = false;

      for (const f of fruits) {
        const g = f.group;
        const grabbed = isGrabbed(g);
        if (grabbed) {
          if (f.inBasket) {
            f.inBasket = false;
            panelDirty = true;
          }
          f.wasGrabbed = true;
          const dx = g.position.x - basketX;
          const dz = g.position.z - basketZ;
          if (dx * dx + dz * dz < 0.0144 && g.position.y < 0.26) hover = true;
        } else {
          if (f.inBasket) {
            const k = Math.min(1, d * 10);
            g.position.x += (f.slot[0] - g.position.x) * k;
            g.position.y += (f.slot[1] - g.position.y) * k;
            g.position.z += (f.slot[2] - g.position.z) * k;
            f.wasGrabbed = false;
          } else {
            if (f.wasGrabbed) {
              const dx = g.position.x - basketX;
              const dz = g.position.z - basketZ;
              const dist2 = dx * dx + dz * dz;
              if (dist2 < 0.010 && g.position.y < 0.22 && g.position.y > 0.015) {
                f.inBasket = true;
                g.position.set(f.slot[0], f.slot[1], f.slot[2]);
                panelDirty = true;
              }
              f.wasGrabbed = false;
            }
            if (!f.inBasket && g.position.y > f.restY) {
              g.position.y -= d * 0.3;
              if (g.position.y < f.restY) g.position.y = f.restY;
            }
            if (!f.inBasket && g.position.y < f.restY) g.position.y = f.restY;
          }
        }
      }

      if (panelDirty) refreshPanel();

      rimMat.emissiveIntensity = hover ? 0.9 + 0.4 * Math.sin(time * 7) : 0.25;

      let inCount = 0;
      for (const f of fruits) if (f.inBasket) inCount += 1;
      arrow.visible = inCount < 3;
      if (arrow.visible) {
        arrow.position.y = 0.29 + 0.012 * Math.sin(time * 2.2);
        arrow.rotation.y = time * 0.8;
      }
    },
  };
}

