      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------------------------------------------------------- helix
  const helix = new THREE.Group();
  helix.name = 'DNA';
  helix.position.set(-0.09, 0.16, 0);
  helix.rotation.y = 0.35;
  root.add(helix);

  const R = 0.05;      // helix radius
  const H = 0.28;      // height
  const TURNS = 2.5;   // full twists

  const _m = new THREE.Matrix4();
  const _c = new THREE.Color();
  const up = new THREE.Vector3(0, 1, 0);

  // --- sugar-phosphate backbones: two strands of beads -------------------
  const N = 48;
  const sphereGeo = new THREE.SphereGeometry(0.011, 12, 8);
  const backboneMat = new THREE.MeshStandardMaterial({
    color: 0xffffff, roughness: 0.35, metalness: 0.2,
  });
  const backbone = new THREE.InstancedMesh(sphereGeo, backboneMat, N * 2);
  backbone.name = 'backbone';

  const strandColors = [0x7f9cff, 0xffa04d];
  let k = 0;
  for (let s = 0; s < 2; s++) {
    for (let i = 0; i < N; i++) {
      const t = i / (N - 1);
      const a = t * TURNS * Math.PI * 2 + s * Math.PI;
      _m.makeTranslation(Math.cos(a) * R, t * H - H / 2, Math.sin(a) * R);
      backbone.setMatrixAt(k, _m);
      _c.setHex(strandColors[s]);
      backbone.setColorAt(k, _c);
      k++;
    }
  }
  backbone.instanceMatrix.needsUpdate = true;
  backbone.instanceColor.needsUpdate = true;
  helix.add(backbone);

  // --- base pairs: 12 rungs, each split into two coloured bases ----------
  const PAIRS = [
    ['A', 'T'], ['G', 'C'], ['T', 'A'], ['C', 'G'], ['G', 'C'], ['A', 'T'],
    ['C', 'G'], ['T', 'A'], ['A', 'T'], ['G', 'C'], ['C', 'G'], ['A', 'T'],
  ];
  const BASE_COLORS = { A: 0xff5a5a, T: 0x5aa9ff, G: 0x5ce08a, C: 0xffd24d };

  const rungGeo = new THREE.CylinderGeometry(0.005, 0.005, 1, 6, 1);
  const rungMat = new THREE.MeshStandardMaterial({
    color: 0xffffff, roughness: 0.5, metalness: 0.05,
  });
  const rungs = new THREE.InstancedMesh(rungGeo, rungMat, PAIRS.length * 2);
  rungs.name = 'basePairs';

  const pa = new THREE.Vector3();
  const pb = new THREE.Vector3();
  const dir = new THREE.Vector3();
  const mid = new THREE.Vector3();
  const q = new THREE.Quaternion();
  const scl = new THREE.Vector3(1, R, 1);

  let r = 0;
  for (let i = 0; i < PAIRS.length; i++) {
    const t = (i + 0.5) / PAIRS.length;
    const a = t * TURNS * Math.PI * 2;
    const y = t * H - H / 2;
    pa.set(Math.cos(a) * R, y, Math.sin(a) * R);
    pb.set(-Math.cos(a) * R, y, -Math.sin(a) * R);
    dir.subVectors(pb, pa).normalize();
    q.setFromUnitVectors(up, dir);

    mid.copy(pa).addScaledVector(dir, R * 0.5);
    _m.compose(mid, q, scl);
    rungs.setMatrixAt(r, _m);
    _c.setHex(BASE_COLORS[PAIRS[i][0]]);
    rungs.setColorAt(r, _c);
    r++;

    mid.copy(pa).addScaledVector(dir, R * 1.5);
    _m.compose(mid, q, scl);
    rungs.setMatrixAt(r, _m);
    _c.setHex(BASE_COLORS[PAIRS[i][1]]);
    rungs.setColorAt(r, _c);
    r++;
  }
  rungs.instanceMatrix.needsUpdate = true;
  rungs.instanceColor.needsUpdate = true;
  helix.add(rungs);

  // ---------------------------------------------------------------- panel
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px;
              background-color: #1a1d22; border-width: 1px; border-color: #333a44; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .body { color: #cfd6e0; font-size: 20px; }
      .row { flex-direction: row; gap: 10px; align-items: center; }
      .btn { padding-top: 9px; padding-bottom: 9px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .alt { background-color: #3b4250; }
      .btntext { color: #ffffff; font-size: 19px; font-weight: 700; }
      .dot { width: 16px; height: 16px; border-radius: 8px; }
      .dotA { background-color: #ff5a5a; }
      .dotT { background-color: #5aa9ff; }
      .dotG { background-color: #5ce08a; }
      .dotC { background-color: #ffd24d; }
      .lbl { color: #cfd6e0; font-size: 18px; }
    </style>
    <div class="card">
      <span class="title">DNA double helix</span>
      <span class="body" id="fact">Pinch the helix to pick it up and turn it in your hand.</span>
      <div class="row">
        <button class="btn" id="spin"><span class="btntext" id="spinlabel">Spin</span></button>
        <button class="btn alt" id="turn"><span class="btntext">Turn 90°</span></button>
      </div>
      <div class="row">
        <button class="btn alt" id="factbtn"><span class="btntext">Next fact</span></button>
      </div>
      <div class="row">
        <div class="dot dotA"></div><span class="lbl">A</span>
        <div class="dot dotT"></div><span class="lbl">T</span>
        <div class="dot dotG"></div><span class="lbl">G</span>
        <div class="dot dotC"></div><span class="lbl">C</span>
      </div>
    </div>`, { width: 0.34, position: [0.28, 0.17, 0.02], rotationY: -0.4 });
  root.add(info.object3D);

  // ---------------------------------------------------------------- state
  const facts = [
    'The two strands are antiparallel: they run in opposite directions.',
    'A always pairs with T (2 hydrogen bonds); G pairs with C (3 hydrogen bonds).',
    'One full turn of B-DNA covers about 10 base pairs and rises 3.4 nm.',
    'Each of your cells holds roughly 3 billion base pairs of DNA.',
    'The double helix was described in 1953, using Rosalind Franklin’s X-ray images.',
    'The sugar-phosphate backbones sit on the outside; the bases point inward.',
  ];
  let factIndex = 0;

  const SPIN_SPEED = 0.5;   // rad/s -> rim speed 0.025 m/s
  const TURN_SPEED = 0.9;   // rad/s -> rim speed 0.045 m/s
  let spinning = false;
  let targetAngle = helix.rotation.y;

  function setSpin(on) {
    spinning = on;
    if (!on) targetAngle = helix.rotation.y;
    info.set('spinlabel', { text: on ? 'Stop' : 'Spin' });
    info.set('spin', { backgroundColor: on ? '#c2410c' : '#2f6fdb' });
  }

  info.on('spin', 'click', () => setSpin(!spinning));
  info.on('turn', 'click', () => {
    if (spinning) setSpin(false);
    targetAngle = helix.rotation.y + Math.PI / 2;
  });
  info.on('factbtn', 'click', () => {
    factIndex = (factIndex + 1) % facts.length;
    info.set('fact', { text: facts[factIndex] });
  });

  traits(helix, { grab: true, onPress: () => setSpin(!spinning) });

  // ---------------------------------------------------------------- loop
  return {
    root,
    update(time, delta) {
      if (isGrabbed(helix)) {
        targetAngle = helix.rotation.y; // resync, never fight the hand
        return;
      }
      if (spinning) {
        helix.rotation.y += SPIN_SPEED * delta;
        targetAngle = helix.rotation.y;
      } else {
        const d = targetAngle - helix.rotation.y;
        if (Math.abs(d) > 1e-4) {
          const step = Math.min(Math.abs(d), TURN_SPEED * delta);
          helix.rotation.y += Math.sign(d) * step;
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const TAU = Math.PI * 2;

  // ---------------- materials (shared) ----------------
  const bodyMat = new THREE.MeshStandardMaterial({ color: 0x2c313a, roughness: 0.42, metalness: 0.75 });
  const rimMat = new THREE.MeshStandardMaterial({ color: 0x99a2ae, roughness: 0.28, metalness: 0.9 });
  const faceMat = new THREE.MeshStandardMaterial({ color: 0xf3f0e8, roughness: 0.95, metalness: 0.0 });
  const inkMat = new THREE.MeshStandardMaterial({ color: 0x22262c, roughness: 0.6, metalness: 0.1 });
  const handMat = new THREE.MeshStandardMaterial({ color: 0x1b1f25, roughness: 0.45, metalness: 0.4 });
  const secondMat = new THREE.MeshStandardMaterial({
    color: 0xd94a3d, roughness: 0.5, metalness: 0.2,
    emissive: 0x54110d, emissiveIntensity: 0.6,
  });

  // ---------------- the clock ----------------
  const clock = new THREE.Group();
  clock.name = 'DeskClock';
  clock.position.set(-0.13, 0, 0);
  root.add(clock);

  // foot
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.052, 0.061, 0.016, 32), bodyMat);
  base.name = 'ClockBase';
  base.position.y = 0.008;
  clock.add(base);

  // neck
  const stem = new THREE.Mesh(new THREE.BoxGeometry(0.028, 0.046, 0.020), bodyMat);
  stem.name = 'ClockStem';
  stem.position.y = 0.032;
  clock.add(stem);

  // round case, flat faces pointing at the user
  const bodyGeo = new THREE.CylinderGeometry(0.085, 0.085, 0.030, 48);
  bodyGeo.rotateX(Math.PI / 2);
  const body = new THREE.Mesh(bodyGeo, bodyMat);
  body.name = 'ClockBody';
  body.position.y = 0.115;
  clock.add(body);

  // dial
  const face = new THREE.Mesh(new THREE.CircleGeometry(0.076, 48), faceMat);
  face.name = 'ClockFace';
  face.position.set(0, 0.115, 0.0154);
  clock.add(face);

  const bezel = new THREE.Mesh(new THREE.RingGeometry(0.076, 0.0845, 48), rimMat);
  bezel.name = 'ClockBezel';
  bezel.position.set(0, 0.115, 0.0152);
  clock.add(bezel);

  // hour ticks
  const tickGeo = new THREE.BoxGeometry(0.0035, 0.008, 0.0018);
  const tickBigGeo = new THREE.BoxGeometry(0.0055, 0.013, 0.0018);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU;
    const big = i % 3 === 0;
    const t = new THREE.Mesh(big ? tickBigGeo : tickGeo, inkMat);
    const r = 0.0615;
    t.position.set(Math.sin(a) * r, 0.115 + Math.cos(a) * r, 0.0168);
    t.rotation.z = -a;
    clock.add(t);
  }

  // hands (each on its own pivot, pointing up at 12)
  const hourGeo = new THREE.BoxGeometry(0.0075, 0.038, 0.0015);
  hourGeo.translate(0, 0.038 / 2 - 0.006, 0);
  const minuteGeo = new THREE.BoxGeometry(0.0055, 0.056, 0.0015);
  minuteGeo.translate(0, 0.056 / 2 - 0.006, 0);
  const secondGeo = new THREE.BoxGeometry(0.0022, 0.064, 0.0012);
  secondGeo.translate(0, 0.064 / 2 - 0.010, 0);

  const hourHand = new THREE.Group();
  hourHand.name = 'HourHand';
  hourHand.position.set(0, 0.115, 0.0190);
  hourHand.add(new THREE.Mesh(hourGeo, handMat));
  clock.add(hourHand);

  const minuteHand = new THREE.Group();
  minuteHand.name = 'MinuteHand';
  minuteHand.position.set(0, 0.115, 0.0205);
  minuteHand.add(new THREE.Mesh(minuteGeo, handMat));
  clock.add(minuteHand);

  const secondHand = new THREE.Group();
  secondHand.name = 'SecondHand';
  secondHand.position.set(0, 0.115, 0.0225);
  secondHand.add(new THREE.Mesh(secondGeo, secondMat));
  clock.add(secondHand);

  // centre hub
  const hubGeo = new THREE.CylinderGeometry(0.0075, 0.0075, 0.009, 24);
  hubGeo.rotateX(Math.PI / 2);
  const hub = new THREE.Mesh(hubGeo, rimMat);
  hub.name = 'ClockHub';
  hub.position.set(0, 0.115, 0.0205);
  clock.add(hub);

  // ---------------- readout panel ----------------
  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; align-items: center; gap: 10px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 24px; padding-right: 24px;
              background-color: #191c21; border-radius: 22px; }
      .title { color: #8f9aab; font-size: 18px; font-weight: 700; text-align: center; }
      .time { color: #ffffff; font-size: 66px; font-weight: 700; text-align: center; }
      .sub { color: #cdd4de; font-size: 19px; text-align: center; }
      .row { display: flex; flex-direction: row; gap: 12px; margin-top: 6px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px;
             border-radius: 14px; background-color: #2b3038; }
      .btn-text { color: #eaf0f8; font-size: 19px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DESK CLOCK</span>
      <span class="time" id="time">--:--</span>
      <span class="sub">Pinch to move · press the clock to switch format</span>
      <div class="row">
        <button class="btn" id="fmt"><span class="btn-text" id="fmt-text">12-hour</span></button>
        <button class="btn" id="sec"><span class="btn-text" id="sec-text">Second hand: on</span></button>
      </div>
    </div>`, { width: 0.30, position: [0.14, 0.13, 0.03], rotationY: -0.35 });
  root.add(panel.object3D);

  // ---------------- time logic ----------------
  const tzOffsetMs = new Date().getTimezoneOffset() * 60000; // local = UTC - offset

  let use24 = true;
  let showSeconds = true;
  let curH = -1;
  let curM = -1;

  function pad2(n) { return n < 10 ? '0' + n : '' + n; }

  function renderDigital() {
    let txt;
    if (use24) {
      txt = pad2(curH) + ':' + pad2(curM);
    } else {
      const h12 = curH % 12 === 0 ? 12 : curH % 12;
      txt = h12 + ':' + pad2(curM) + (curH < 12 ? ' AM' : ' PM');
    }
    panel.set('time', { text: txt });
  }

  function renderFormatLabel() {
    panel.set('fmt-text', { text: use24 ? '12-hour' : '24-hour' });
  }

  function renderSecondsLabel() {
    panel.set('sec-text', { text: showSeconds ? 'Second hand: on' : 'Second hand: off' });
  }

  function toggleFormat() {
    use24 = !use24;
    renderFormatLabel();
    if (curH >= 0) renderDigital();
  }

  function toggleSeconds() {
    showSeconds = !showSeconds;
    secondHand.visible = showSeconds;
    renderSecondsLabel();
  }

  renderFormatLabel();
  renderSecondsLabel();

  panel.on('fmt', 'click', toggleFormat);
  panel.on('sec', 'click', toggleSeconds);

  traits(clock, { grab: true, onPress: toggleFormat });

  return {
    root,
    update(time, delta) {
      const localSec = (Date.now() - tzOffsetMs) / 1000;
      const s = Math.floor(localSec) % 60;
      const m = Math.floor(localSec / 60) % 60;
      const h = Math.floor(localSec / 3600) % 24;

      if (h !== curH || m !== curM) {
        curH = h;
        curM = m;
        renderDigital();
      }

      hourHand.rotation.z = -(((h % 12) + m / 60 + s / 3600) / 12) * TAU;
      minuteHand.rotation.z = -(((m + s / 60) / 60)) * TAU;
      if (showSeconds) {
        secondHand.rotation.z = -((localSec % 60) / 60) * TAU;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
