        <span class="status" id="colorName">Cyan • #22D3EE</span>
      </div>
      <span class="count" id="pressCount">Presses: 0</span>
    </div>`, { width: 0.32, position: [0, 0.19, -0.035] });
  root.add(panel.object3D);

  let colorIndex = 0;
  let presses = 0;
  let pressDepth = 0;
  let flash = 0;

  function applyColor(index) {
    const color = palette[index];
    buttonMaterial.color.setHex(color.hex).multiplyScalar(0.5);
    buttonMaterial.emissive.setHex(color.hex);
    glowMaterial.color.setHex(color.hex);
