      colorIndex = (colorIndex + 1) % palette.length;
      presses += 1;
      applyColor(colorIndex);
      panel.set('pressCount', { text: 'Presses: ' + presses });
      pressDepth = 0.009;
      flash = 1;
    },
  });

  applyColor(colorIndex);

  return {
    root,
    update(time, delta) {
      const pulse = Math.sin(time * 2.4);
      buttonMaterial.emissiveIntensity = 1.45 + pulse * 0.22 + flash * 1.4;
      glowMaterial.opacity = Math.min(1, 0.68 + pulse * 0.16 + flash * 0.16);
      buttonRing.scale.setScalar(1 + pulse * 0.025 + flash * 0.06);

      pressDepth *= Math.exp(-delta * 11);
      flash = Math.max(0, flash - delta * 2.5);
      button.position.y = buttonRestY - pressDepth;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  root.name = 'Interactive DNA';

  const dna = new THREE.Group();
  dna.name = 'DNA double helix';
  const homePosition = new THREE.Vector3(-0.16, 0.18, 0);
  dna.position.copy(homePosition);
  root.add(dna);

  const sequence = ['A', 'T', 'G', 'C', 'C', 'G', 'T', 'A', 'A', 'T', 'G', 'C'];
  const complement = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const pairCount = sequence.length;
  const radius = 0.071;
  const rise = (2 * radius * 1.7) / 10.5;
  const halfHeight = ((pairCount - 1) * rise) / 2;
  const angleStep = (Math.PI * 2) / 10.5;

  const cyanMaterial = new THREE.MeshStandardMaterial({
    color: 0x8ed9e5,
    roughness: 0.4,
    metalness: 0.15,
  });
  const violetMaterial = new THREE.MeshStandardMaterial({
    color: 0xc4a0f0,
    roughness: 0.4,
    metalness: 0.15,
  });
  const baseMaterials = {
    A: new THREE.MeshStandardMaterial({ color: 0x41c98e, roughness: 0.45 }),
    T: new THREE.MeshStandardMaterial({ color: 0xff735f, roughness: 0.45 }),
    G: new THREE.MeshStandardMaterial({ color: 0xf3c857, roughness: 0.45 }),
    C: new THREE.MeshStandardMaterial({ color: 0x5ea7ff, roughness: 0.45 }),
  };
  const hydrogenMaterial = new THREE.MeshStandardMaterial({
    color: 0xe8fbff,
    emissive: 0x73dfff,
    emissiveIntensity: 0.45,
    roughness: 0.25,
  });

  const strandOnePoints = [];
  const strandTwoPoints = [];

  for (let i = 0; i < pairCount; i++) {
    // Decreasing azimuth with increasing Y gives a right-handed helix.
    const angle = -i * angleStep;
    const y = i * rise - halfHeight;
    const x = Math.cos(angle) * radius;
    const z = Math.sin(angle) * radius;
    strandOnePoints.push(new THREE.Vector3(x, y, z));
    strandTwoPoints.push(new THREE.Vector3(-x, y, -z));
  }

  function addBackbone(points, material, name) {
    const curve = new THREE.CatmullRomCurve3(points, false, 'centripetal');
    const tube = new THREE.Mesh(
      new THREE.TubeGeometry(curve, 120, 0.0038, 6, false),
      material,
    );
    tube.name = name;
    dna.add(tube);
  }

  addBackbone(strandOnePoints, cyanMaterial, 'Cyan sugar-phosphate backbone');
  addBackbone(strandTwoPoints, violetMaterial, 'Violet sugar-phosphate backbone');

  const dummy = new THREE.Object3D();
  const nodeGeometry = new THREE.SphereGeometry(0.0065, 16, 10);

  function addNodes(points, material, name) {
    const mesh = new THREE.InstancedMesh(nodeGeometry, material, points.length);
    mesh.name = name;
    for (let i = 0; i < points.length; i++) {
      dummy.position.copy(points[i]);
      dummy.quaternion.identity();
      dummy.scale.setScalar(1);
      dummy.updateMatrix();
      mesh.setMatrixAt(i, dummy.matrix);
    }
    mesh.instanceMatrix.needsUpdate = true;
    dna.add(mesh);
  }

  addNodes(strandOnePoints, cyanMaterial, 'Cyan backbone nucleotides');
  addNodes(strandTwoPoints, violetMaterial, 'Violet backbone nucleotides');

  const baseSegments = { A: [], T: [], G: [], C: [] };
  const hydrogenPositions = [];
  const center = new THREE.Vector3();

  for (let i = 0; i < pairCount; i++) {
    const first = sequence[i];
    const second = complement[first];
    const p1 = strandOnePoints[i];
    const p2 = strandTwoPoints[i];

    baseSegments[first].push([p1.clone().multiplyScalar(0.9), p1.clone().multiplyScalar(0.08)]);
    baseSegments[second].push([p2.clone().multiplyScalar(0.9), p2.clone().multiplyScalar(0.08)]);

    const bondCount = first === 'A' || first === 'T' ? 2 : 3;
    for (let b = 0; b < bondCount; b++) {
      center.set(0, p1.y + (b - (bondCount - 1) / 2) * 0.0035, 0);
      hydrogenPositions.push(center.clone());
    }
  }

  const cylinderGeometry = new THREE.CylinderGeometry(1, 1, 1, 10, 1);
  const yAxis = new THREE.Vector3(0, 1, 0);
  const direction = new THREE.Vector3();

  function addBaseInstances(letter) {
    const segments = baseSegments[letter];
    const mesh = new THREE.InstancedMesh(cylinderGeometry, baseMaterials[letter], segments.length);
    mesh.name = letter + ' bases';

    for (let i = 0; i < segments.length; i++) {
      const start = segments[i][0];
      const end = segments[i][1];
      direction.copy(end).sub(start);
      const length = direction.length();
      direction.normalize();

      dummy.position.copy(start).add(end).multiplyScalar(0.5);
      dummy.quaternion.setFromUnitVectors(yAxis, direction);
      dummy.scale.set(0.0044, length, 0.0044);
      dummy.updateMatrix();
      mesh.setMatrixAt(i, dummy.matrix);
    }

    mesh.instanceMatrix.needsUpdate = true;
    dna.add(mesh);
  }

  addBaseInstances('A');
  addBaseInstances('T');
  addBaseInstances('G');
  addBaseInstances('C');

  const hydrogenGeometry = new THREE.SphereGeometry(0.002, 10, 6);
  const hydrogenBonds = new THREE.InstancedMesh(
    hydrogenGeometry,
    hydrogenMaterial,
    hydrogenPositions.length,
  );
  hydrogenBonds.name = 'Hydrogen bonds between base pairs';

  for (let i = 0; i < hydrogenPositions.length; i++) {
    dummy.position.copy(hydrogenPositions[i]);
    dummy.quaternion.identity();
    dummy.scale.setScalar(1);
    dummy.updateMatrix();
    hydrogenBonds.setMatrixAt(i, dummy.matrix);
  }
  hydrogenBonds.instanceMatrix.needsUpdate = true;
  dna.add(hydrogenBonds);

  // Arrowheads indicate the antiparallel 5′→3′ backbone directions.
  const arrowGeometry = new THREE.ConeGeometry(0.007, 0.016, 12);
  const upwardArrow = new THREE.Mesh(arrowGeometry, cyanMaterial);
  upwardArrow.name = 'Cyan strand 5-prime to 3-prime direction';
  upwardArrow.position.set(
    strandOnePoints[pairCount - 1].x,
    halfHeight + 0.013,
    strandOnePoints[pairCount - 1].z,
  );
  dna.add(upwardArrow);

  const downwardArrow = new THREE.Mesh(arrowGeometry, violetMaterial);
  downwardArrow.name = 'Violet strand 5-prime to 3-prime direction';
  downwardArrow.position.set(strandTwoPoints[0].x, -halfHeight - 0.013, strandTwoPoints[0].z);
  downwardArrow.rotation.z = Math.PI;
  dna.add(downwardArrow);

  const stand = new THREE.Mesh(
    new THREE.CylinderGeometry(0.078, 0.084, 0.014, 32),
    new THREE.MeshStandardMaterial({
      color: 0x252b33,
      roughness: 0.55,
      metalness: 0.35,
    }),
  );
  stand.name = 'Reset stand';
  stand.position.set(homePosition.x, 0.007, 0);
  root.add(stand);

  const glowMaterial = new THREE.MeshStandardMaterial({
    color: 0x60cfe5,
    emissive: 0x2d9dbd,
    emissiveIntensity: 0.65,
    roughness: 0.35,
  });
  const glowRing = new THREE.Mesh(new THREE.TorusGeometry(0.068, 0.0016, 8, 48), glowMaterial);
  glowRing.name = 'Stand glow ring';
  glowRing.rotation.x = Math.PI / 2;
  glowRing.position.set(homePosition.x, 0.015, 0);
  root.add(glowRing);

  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; width: 520px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 22px; padding-right: 22px;
              border-radius: 18px; background-color: #1f232a; border-color: #3b4654; border-width: 1px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #dce3eb; font-size: 21px; }
      .key { flex-direction: row; gap: 8px; align-items: center; justify-content: center; }
      .chip { padding-top: 7px; padding-bottom: 7px; padding-left: 10px; padding-right: 10px;
              border-radius: 10px; color: #ffffff; font-size: 20px; font-weight: 700; }
      .a { background-color: #176b4b; }
      .t { background-color: #873b32; }
      .g { background-color: #f3c857; color: #1a1d22; }
      .c { background-color: #24588c; }
      .fact { color: #b9dce8; font-size: 20px; }
      .buttons { flex-direction: row; gap: 12px; }
      .button { padding-top: 11px; padding-bottom: 11px; padding-left: 16px; padding-right: 16px;
                border-radius: 12px; background-color: #326e9e; }
      .secondary { background-color: #353c46; }
      .button-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA double helix</span>
      <span class="body">Pinch and hold the model, then move or twist your hand to inspect it. Tap the base to recenter.</span>
      <div class="key">
        <span class="chip a">A adenine</span>
        <span class="chip t">T thymine</span>
        <span class="chip g">G guanine</span>
        <span class="chip c">C cytosine</span>
      </div>
      <span class="fact" id="fact">A–T has 2 hydrogen bonds; G–C has 3. The glowing beads show these bonds.</span>
      <div class="buttons">
        <button class="button" id="next"><span class="button-text">Next fact</span></button>
        <button class="button secondary" id="reset"><span class="button-text">Reset helix</span></button>
      </div>
    </div>`, { width: 0.37, position: [0.19, 0.205, 0.015], rotationY: -0.3 });
  root.add(panel.object3D);

  const facts = [
    'A–T has 2 hydrogen bonds; G–C has 3. The glowing beads show these bonds.',
    'The strands are antiparallel: the cyan backbone runs 5′→3′ upward; violet runs downward.',
    'B-DNA is right-handed, with about 10.5 base pairs and 3.4 nm per complete turn.',
    'Cyan sequence, bottom→top: 5′-ATGCCGTAATGC-3′. Violet is its complementary strand.',
    'Bases carry genetic information; sugars and phosphates form the protective outer backbones.',
  ];
  let factIndex = 0;

  function resetHelix() {
    dna.position.copy(homePosition);
    dna.quaternion.identity();
    dna.scale.set(1, 1, 1);
    factIndex = 0;
    panel.set('fact', { text: facts[factIndex] });
  }

  panel.on('next', 'click', () => {
    factIndex = (factIndex + 1) % facts.length;
    panel.set('fact', { text: facts[factIndex] });
  });
  panel.on('reset', 'click', resetHelix);

  traits(dna, { grab: true });
  traits(stand, { onPress: resetHelix });

  return {
    root,
    update(time) {
      if (isGrabbed(dna)) return;
      hydrogenMaterial.emissiveIntensity = 0.45 + Math.sin(time * 2) * 0.12;
      glowMaterial.emissiveIntensity = 0.65 + Math.sin(time * 1.4) * 0.12;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const pairCount = 21; // Two turns at approximately 10.5 bp per turn.
  const radius = 0.066;
  const rise = 0.0145;
  const angleStep = (Math.PI * 2) / 10.5;
  const innerGap = 0.009;
  const sequence = [
    'A', 'T', 'G', 'C', 'C', 'G', 'T',
    'A', 'A', 'G', 'A', 'T', 'C', 'G',
    'G', 'C', 'A', 'T', 'G', 'C', 'A',
  ];
  const complement = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const baseNames = {
    A: 'Adenine',
    T: 'Thymine',
    G: 'Guanine',
    C: 'Cytosine',
  };
  const baseColors = {
    A: new THREE.Color(0xf4c95d),
    T: new THREE.Color(0xef6a6a),
    G: new THREE.Color(0x48bfe3),
    C: new THREE.Color(0xb892ff),
  };

  const helix = new THREE.Group();
  helix.name = 'DNA double helix — pinch to pick up and rotate';
  helix.position.set(-0.13, 0.2, 0);
  root.add(helix);

  const pointsA = [];
  const pointsB = [];
  for (let i = 0; i < pairCount; i++) {
    const theta = i * angleStep;
    const y = (i - (pairCount - 1) / 2) * rise;
    // Increasing y follows a right-handed helix.
    pointsA.push(new THREE.Vector3(
      radius * Math.cos(theta),
      y,
      -radius * Math.sin(theta),
    ));
    pointsB.push(new THREE.Vector3(
      -radius * Math.cos(theta),
      y,
      radius * Math.sin(theta),
    ));
  }

  const strandMaterialA = new THREE.MeshStandardMaterial({
    color: 0x63e6e2,
    emissive: 0x1c8f91,
    emissiveIntensity: 0.22,
    roughness: 0.38,
  });
  const strandMaterialB = new THREE.MeshStandardMaterial({
    color: 0xff8fa3,
    emissive: 0x9b3451,
    emissiveIntensity: 0.18,
    roughness: 0.38,
  });

  const backboneA = new THREE.Mesh(
    new THREE.TubeGeometry(
      new THREE.CatmullRomCurve3(pointsA, false, 'centripetal'),
      220,
      0.0054,
      8,
      false,
    ),
    strandMaterialA,
  );
  backboneA.name = 'Cyan sugar-phosphate backbone: 5 prime bottom to 3 prime top';
  helix.add(backboneA);

  const backboneB = new THREE.Mesh(
    new THREE.TubeGeometry(
      new THREE.CatmullRomCurve3(pointsB, false, 'centripetal'),
      220,
      0.0054,
      8,
      false,
    ),
    strandMaterialB,
  );
  backboneB.name = 'Pink sugar-phosphate backbone: 5 prime top to 3 prime bottom';
  helix.add(backboneB);

  const dummy = new THREE.Object3D();
  const beadGeometry = new THREE.SphereGeometry(0.0075, 12, 8);
  const beadsA = new THREE.InstancedMesh(beadGeometry, strandMaterialA, pairCount);
  const beadsB = new THREE.InstancedMesh(beadGeometry, strandMaterialB, pairCount);
  beadsA.name = 'Cyan backbone sugars';
  beadsB.name = 'Pink backbone sugars';

  for (let i = 0; i < pairCount; i++) {
    dummy.position.copy(pointsA[i]);
    dummy.quaternion.identity();
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    beadsA.setMatrixAt(i, dummy.matrix);

    dummy.position.copy(pointsB[i]);
    dummy.updateMatrix();
    beadsB.setMatrixAt(i, dummy.matrix);
  }
  beadsA.instanceMatrix.needsUpdate = true;
  beadsB.instanceMatrix.needsUpdate = true;
  helix.add(beadsA, beadsB);

  const up = new THREE.Vector3(0, 1, 0);
  const start = new THREE.Vector3();
  const end = new THREE.Vector3();
  const midpoint = new THREE.Vector3();
  const direction = new THREE.Vector3();

  function placeCylinder(mesh, index, ax, ay, az, bx, by, bz) {
    start.set(ax, ay, az);
    end.set(bx, by, bz);
    direction.subVectors(end, start);
    const length = direction.length();
    midpoint.addVectors(start, end).multiplyScalar(0.5);

    dummy.position.copy(midpoint);
    dummy.quaternion.setFromUnitVectors(up, direction.normalize());
    dummy.scale.set(1, length, 1);
    dummy.updateMatrix();
    mesh.setMatrixAt(index, dummy.matrix);
  }

  const baseMaterial = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.42,
    metalness: 0.04,
  });
  const bases = new THREE.InstancedMesh(
    new THREE.CylinderGeometry(0.0058, 0.0058, 1, 8, 1),
    baseMaterial,
    pairCount * 2,
  );
  bases.name = 'Paired nucleobases: adenine thymine guanine cytosine';
  helix.add(bases);

  const bondTotal = sequence.reduce(
    (total, letter) => total + ((letter === 'A' || letter === 'T') ? 2 : 3),
    0,
  );
  const bonds = new THREE.InstancedMesh(
    new THREE.CylinderGeometry(0.00115, 0.00115, 1, 6, 1),
    new THREE.MeshStandardMaterial({
      color: 0xf2fbff,
      emissive: 0xa9e8ff,
      emissiveIntensity: 0.65,
      roughness: 0.25,
    }),
    bondTotal,
  );
  bonds.name = 'Hydrogen bonds: two for A-T and three for G-C';
  helix.add(bonds);

  let bondIndex = 0;
  for (let i = 0; i < pairCount; i++) {
    const theta = i * angleStep;
    const y = (i - (pairCount - 1) / 2) * rise;
    const rx = Math.cos(theta);
    const rz = -Math.sin(theta);
    const outer = radius - 0.005;

    placeCylinder(
      bases, i * 2,
      rx * outer, y, rz * outer,
      rx * innerGap, y, rz * innerGap,
    );
    placeCylinder(
      bases, i * 2 + 1,
      -rx * outer, y, -rz * outer,
      -rx * innerGap, y, -rz * innerGap,
    );

    const letter = sequence[i];
    const other = complement[letter];
    bases.setColorAt(i * 2, baseColors[letter]);
    bases.setColorAt(i * 2 + 1, baseColors[other]);

    const count = (letter === 'A' || letter === 'T') ? 2 : 3;
    for (let k = 0; k < count; k++) {
      const offsetY = (k - (count - 1) / 2) * 0.0025;
      placeCylinder(
        bonds, bondIndex++,
        rx * innerGap, y + offsetY, rz * innerGap,
        -rx * innerGap, y + offsetY, -rz * innerGap,
      );
    }
  }
  bases.instanceMatrix.needsUpdate = true;
  bases.instanceColor.needsUpdate = true;
  bonds.instanceMatrix.needsUpdate = true;

  const highlight = new THREE.Mesh(
    new THREE.TorusGeometry(radius + 0.016, 0.0018, 6, 56),
    new THREE.MeshStandardMaterial({
      color: 0xffdf75,
      emissive: 0xffb52e,
      emissiveIntensity: 0.8,
      roughness: 0.3,
    }),
  );
  highlight.name = 'Selected base-pair indicator';
  highlight.rotation.x = Math.PI / 2;
  helix.add(highlight);

  // Arrowheads follow each strand in its chemical 5′ → 3′ direction.
  function addDirectionArrow(point, theta, reverse, material, name) {
    direction.set(
      -radius * Math.sin(theta),
      rise / angleStep,
      -radius * Math.cos(theta),
    ).normalize();
    if (reverse) direction.negate();

    const arrow = new THREE.Mesh(
      new THREE.ConeGeometry(0.009, 0.023, 12),
      material,
    );
    arrow.name = name;
    arrow.position.copy(point).addScaledVector(direction, 0.013);
    arrow.quaternion.setFromUnitVectors(up, direction);
    helix.add(arrow);
  }

  addDirectionArrow(
    pointsA[pairCount - 1],
    (pairCount - 1) * angleStep,
    false,
    strandMaterialA,
    'Cyan 5 to 3 direction arrow',
  );
  addDirectionArrow(
    pointsB[0],
    Math.PI,
    true,
    strandMaterialB,
    'Pink 5 to 3 direction arrow',
  );

  const pedestal = new THREE.Mesh(
    new THREE.CylinderGeometry(0.108, 0.118, 0.018, 48),
    new THREE.MeshStandardMaterial({
      color: 0x252c35,
      metalness: 0.55,
      roughness: 0.42,
    }),
  );
  pedestal.name = 'DNA display base';
  pedestal.position.set(-0.13, 0.009, 0);
  root.add(pedestal);

  const pedestalRing = new THREE.Mesh(
    new THREE.TorusGeometry(0.091, 0.0022, 6, 48),
    new THREE.MeshStandardMaterial({
      color: 0x63e6e2,
      emissive: 0x2bbdbb,
      emissiveIntensity: 0.65,
    }),
  );
  pedestalRing.rotation.x = Math.PI / 2;
  pedestalRing.position.set(-0.13, 0.0195, 0);
  root.add(pedestalRing);

  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 10px; width: 520px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 24px; padding-right: 24px;
              border-radius: 20px; background-color: #1d2229;
              border-color: #3b4653; border-width: 2px; }
      .title { color: #ffffff; font-size: 31px; font-weight: 700; }
      .subtitle { color: #9fd9df; font-size: 19px; }
      .instruction { color: #ffffff; font-size: 23px; font-weight: 700; }
      .body { color: #d7dde5; font-size: 20px; }
      .small { color: #b9c3cf; font-size: 18px; }
      .legend { display: flex; flex-direction: row; gap: 12px; }
      .adenine { color: #f4c95d; font-size: 18px; font-weight: 700; }
      .thymine { color: #ef6a6a; font-size: 18px; font-weight: 700; }
      .guanine { color: #48bfe3; font-size: 18px; font-weight: 700; }
      .cytosine { color: #b892ff; font-size: 18px; font-weight: 700; }
      .pair { color: #ffdf75; font-size: 23px; font-weight: 700; }
      .buttons { display: flex; flex-direction: row; gap: 12px; margin-top: 4px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #356bd8; }
      .btn-alt { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px;
                 border-radius: 12px; background-color: #394450; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA double helix</span>
      <span class="subtitle">B-DNA · right-handed · ~10.5 bp per turn</span>
      <span class="instruction">Pinch DNA to grab · twist to turn it</span>
      <span class="body">Arrowheads point 5′ → 3′. The cyan and pink sugar–phosphate backbones run antiparallel.</span>
      <div class="legend">
        <span class="adenine">A adenine</span>
        <span class="thymine">T thymine</span>
        <span class="guanine">G guanine</span>
        <span class="cytosine">C cytosine</span>
      </div>
      <span class="pair" id="pairTitle">Pair 11 / 21 · A–T</span>
      <span class="body" id="pairInfo">Adenine–thymine · 2 hydrogen bonds</span>
      <span class="small">A–T pairs have 2 H bonds; G–C pairs have 3.</span>
      <div class="buttons">
        <button class="btn" id="next"><span class="btn-text">Next pair</span></button>
        <button class="btn-alt" id="spin"><span class="btn-text" id="spinLabel">Spin model</span></button>
      </div>
    </div>
  `, {
    width: 0.32,
    position: [0.18, 0.195, 0.015],
    rotationY: -0.2,
  });
  root.add(panel.object3D);

  let selectedPair = 0;
  let spinning = false;
  const scratchColor = new THREE.Color();

  function selectPair(index) {
    selectedPair = index;

    for (let i = 0; i < pairCount; i++) {
      const first = sequence[i];
      const second = complement[first];
      const brightness = i === selectedPair ? 1.15 : 0.58;

      scratchColor.copy(baseColors[first]).multiplyScalar(brightness);
      bases.setColorAt(i * 2, scratchColor);
      scratchColor.copy(baseColors[second]).multiplyScalar(brightness);
      bases.setColorAt(i * 2 + 1, scratchColor);
    }
    bases.instanceColor.needsUpdate = true;

    highlight.position.y = (selectedPair - (pairCount - 1) / 2) * rise;

    const first = sequence[selectedPair];
    const second = complement[first];
    const bondCount = (first === 'A' || first === 'T') ? 2 : 3;
    panel.set('pairTitle', {
      text: `Pair ${selectedPair + 1} / ${pairCount} · ${first}–${second}`,
    });
    panel.set('pairInfo', {
      text: `${baseNames[first]}–${baseNames[second].toLowerCase()} · ${bondCount} hydrogen bonds`,
    });
  }

  function nextPair() {
    selectPair((selectedPair + 1) % pairCount);
  }

  panel.on('next', 'click', nextPair);
  panel.on('spin', 'click', () => {
    spinning = !spinning;
    panel.set('spinLabel', { text: spinning ? 'Stop spin' : 'Spin model' });
  });

  traits(helix, {
    grab: true,
    onPress: nextPair,
  });

  selectPair(10);

  return {
    root,
    update(time, delta) {
      if (isGrabbed(helix)) return;

      if (spinning) {
        helix.rotation.y += Math.min(delta, 0.05) * 0.35;
      }
      highlight.material.emissiveIntensity = 0.72 + Math.sin(time * 3) * 0.2;
    },
  };
}

export default function build({ THREE, traits, ui }) {
  const root = new THREE.Group();
  const TAU = Math.PI * 2;
  const now = new Date();
  const twoDigits = [];
  for (let i = 0; i < 60; i += 1) {
    twoDigits.push(i < 10 ? '0' + i : String(i));
  }

  const clock = new THREE.Group();
  clock.name = 'DeskClock';
  clock.position.set(-0.12, 0.145, 0);
  root.add(clock);

  const caseMaterial = new THREE.MeshStandardMaterial({
    color: 0x334155,
    metalness: 0.65,
    roughness: 0.3,
  });
  const faceMaterial = new THREE.MeshStandardMaterial({
    color: 0x101720,
    roughness: 0.78,
  });
  const rimMaterial = new THREE.MeshStandardMaterial({
    color: 0xa9b6c5,
    metalness: 0.85,
    roughness: 0.22,
  });
  const markerMaterial = new THREE.MeshStandardMaterial({
    color: 0xdce6f2,
    emissive: 0x526274,
    emissiveIntensity: 0.2,
    roughness: 0.5,
  });

  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(0.098, 0.098, 0.03, 48),
    caseMaterial,
  );
  body.name = 'ClockBody';
  body.rotation.x = Math.PI / 2;
  clock.add(body);

  const face = new THREE.Mesh(new THREE.CircleGeometry(0.09, 48), faceMaterial);
  face.name = 'ClockFace';
  face.position.z = 0.017;
  clock.add(face);

  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.093, 0.0045, 12, 48), rimMaterial);
  rim.position.z = 0.019;
  clock.add(rim);

  const ticks = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.0035, 0.012, 0.002),
    markerMaterial,
    12,
  );
  ticks.name = 'HourMarkers';
  const markerTransform = new THREE.Object3D();
  for (let i = 0; i < 12; i += 1) {
    const angle = (i / 12) * TAU;
    markerTransform.position.set(
      Math.sin(angle) * 0.075,
      Math.cos(angle) * 0.075,
      0.021,
    );
    markerTransform.rotation.set(0, 0, -angle);
    markerTransform.updateMatrix();
    ticks.setMatrixAt(i, markerTransform.matrix);
  }
  clock.add(ticks);

  const hourMaterial = new THREE.MeshStandardMaterial({
    color: 0xf8fafc,
    emissive: 0x718096,
    emissiveIntensity: 0.16,
    roughness: 0.4,
  });
  const minuteMaterial = hourMaterial.clone();
  minuteMaterial.color.setHex(0xbce7ef);
  const secondMaterial = new THREE.MeshStandardMaterial({
    color: 0xffa94d,
    emissive: 0xff6b1a,
    emissiveIntensity: 0.35,
    roughness: 0.45,
  });

  function makeHand(width, length, depth, material, z) {
    const pivot = new THREE.Group();
    pivot.position.z = z;
    const hand = new THREE.Mesh(new THREE.BoxGeometry(width, length, depth), material);
    hand.position.y = length / 2 - 0.005;
    pivot.add(hand);
    clock.add(pivot);
    return pivot;
  }

  const hourHand = makeHand(0.006, 0.043, 0.0025, hourMaterial, 0.025);
  hourHand.name = 'HourHand';
  const minuteHand = makeHand(0.004, 0.064, 0.002, minuteMaterial, 0.028);
  minuteHand.name = 'MinuteHand';
  const secondHand = makeHand(0.0016, 0.07, 0.0015, secondMaterial, 0.031);
  secondHand.name = 'SecondHand';

  const secondTail = new THREE.Mesh(
    new THREE.BoxGeometry(0.0016, 0.02, 0.0015),
    secondMaterial,
  );
  secondTail.position.y = -0.01;
  secondHand.add(secondTail);

  const centerCap = new THREE.Mesh(
    new THREE.SphereGeometry(0.005, 20, 10),
    rimMaterial,
  );
  centerCap.position.z = 0.034;
  clock.add(centerCap);

  const stem = new THREE.Mesh(
    new THREE.BoxGeometry(0.027, 0.05, 0.025),
    caseMaterial,
  );
  stem.position.set(0, -0.105, -0.006);
  clock.add(stem);

  const base = new THREE.Mesh(
    new THREE.BoxGeometry(0.145, 0.025, 0.074),
    caseMaterial,
  );
  base.name = 'ClockBase';
  base.position.set(0, -0.1325, -0.004);
  clock.add(base);

  const statusLight = new THREE.Mesh(
    new THREE.SphereGeometry(0.0028, 16, 8),
    new THREE.MeshStandardMaterial({
      color: 0x6ee7d8,
      emissive: 0x20c9b0,
      emissiveIntensity: 1.2,
    }),
  );
  statusLight.position.set(0, -0.047, 0.023);
  clock.add(statusLight);

  const panel = ui(`
    <style>
      .card {
        flex-direction: column;
        align-items: center;
        gap: 10px;
        padding-top: 20px;
        padding-bottom: 20px;
        padding-left: 22px;
        padding-right: 22px;
        border-radius: 20px;
        border-width: 2px;
        border-color: #3b4552;
        background-color: #1a1d22;
      }
      .title { color: #aebdcc; font-size: 22px; font-weight: 700; }
      .time { color: #f2fbff; font-size: 32px; font-weight: 700; }
      .period { color: #78e4d4; font-size: 20px; font-weight: 700; }
      .hint { color: #c5ced8; font-size: 20px; text-align: center; }
      .button {
        padding-top: 11px;
        padding-bottom: 11px;
        padding-left: 16px;
        padding-right: 16px;
        border-radius: 12px;
        background-color: #256b78;
      }
      .button-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">LOCAL TIME</span>
      <span class="time" id="time">00:00</span>
      <span class="period" id="period">24 HOUR</span>
      <button class="button" id="modeButton">
        <span class="button-text" id="modeButtonText">Switch to 12-hour</span>
      </button>
      <span class="hint">Hours and minutes update automatically. Tap the clock to change format.</span>
    </div>`, {
    width: 0.26,
    position: [0.16, 0.15, 0],
    rotationY: -0.16,
  });
  root.add(panel.object3D);

  let use24Hour = true;
  let displayedHour = -1;
  let displayedMinute = -1;

  function refreshDisplay() {
    const hours = now.getHours();
    const minutes = now.getMinutes();
    const shownHour = use24Hour ? hours : (hours % 12 || 12);

    panel.set('time', { text: twoDigits[shownHour] + ':' + twoDigits[minutes] });
    panel.set('period', { text: use24Hour ? '24 HOUR' : (hours < 12 ? 'AM' : 'PM') });
    panel.set('modeButtonText', {
      text: use24Hour ? 'Switch to 12-hour' : 'Switch to 24-hour',
    });

    displayedHour = hours;
    displayedMinute = minutes;
  }

  function toggleMode() {
    use24Hour = !use24Hour;
    refreshDisplay();
  }

  panel.on('modeButton', 'click', toggleMode);
  traits(clock, { onPress: toggleMode });
  refreshDisplay();

  return {
    root,
    update() {
      now.setTime(Date.now());

      const seconds = now.getSeconds() + now.getMilliseconds() / 1000;
      const minutes = now.getMinutes() + seconds / 60;
      const hours = (now.getHours() % 12) + minutes / 60;

      hourHand.rotation.z = -(hours / 12) * TAU;
      minuteHand.rotation.z = -(minutes / 60) * TAU;
      secondHand.rotation.z = -(seconds / 60) * TAU;

      if (now.getHours() !== displayedHour || now.getMinutes() !== displayedMinute) {
        refreshDisplay();
      }
    },
  };
}

export default function build({ THREE, traits, ui }) {
  const root = new THREE.Group();
  const clock = new THREE.Group();
  clock.name = 'Desk clock';
  clock.position.set(-0.055, 0.115, 0);
  root.add(clock);

  const housingMaterial = new THREE.MeshStandardMaterial({
