    lightOn = next;
    beam.visible = lightOn;
    lightPool.visible = lightOn;

    diffuserMaterial.color.setHex(lightOn ? 0xffe2a8 : 0x77766f);
    diffuserMaterial.emissive.setHex(lightOn ? 0xffb846 : 0x000000);
