  poolOuter.rotation.x = -Math.PI / 2;
  poolOuter.scale.y = 0.72;
  poolOuter.position.set(0.035, 0.0015, 0.072);
  root.add(poolOuter);

  const poolInner = new THREE.Mesh(
    new THREE.CircleGeometry(0.078, 40),
    poolInnerMaterial,
  );
  poolInner.rotation.x = -Math.PI / 2;
  poolInner.scale.y = 0.72;
  poolInner.position.set(0.035, 0.002, 0.072);
  root.add(poolInner);

  // A physical round power button on the base also toggles the lamp.
  const powerMaterial = new THREE.MeshStandardMaterial({
    color: 0x53d790,
    emissive: 0x36d67f,
    emissiveIntensity: 1.2,
    roughness: 0.3,
    metalness: 0.25,
  });
  const powerButton = new THREE.Mesh(
    new THREE.CylinderGeometry(0.018, 0.018, 0.009, 24),
    powerMaterial,
  );
  powerButton.name = 'Power button';
  powerButton.position.set(-0.045, 0.038, 0.035);
  root.add(powerButton);

  const panel = ui(`
    <style>
      .card {
        flex-direction: column;
        gap: 12px;
        padding-top: 20px;
        padding-bottom: 20px;
        padding-left: 22px;
        padding-right: 22px;
        border-radius: 18px;
        border-width: 1px;
        border-color: #465049;
        background-color: #1d2224;
      }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .row { flex-direction: row; align-items: center; justify-content: space-between; gap: 18px; }
      .label { color: #b9c3c1; font-size: 20px; font-weight: 700; }
      .state {
        width: 74px;
        text-align: center;
        color: #c8ffdb;
        background-color: #28553b;
        font-size: 22px;
        font-weight: 700;
        padding-top: 6px;
        padding-bottom: 6px;
        padding-left: 10px;
        padding-right: 10px;
        border-radius: 12px;
      }
      .hint { color: #edf2f0; font-size: 21px; }
      .sub { color: #aeb9b5; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title">Desk lamp</span>
      <div class="row">
        <span class="label">POWER</span>
        <span class="state" id="state">ON</span>
      </div>
      <span class="hint" id="hint">Press the lamp to switch it off.</span>
      <span class="sub">Shade, arm, base and round button all work.</span>
    </div>`, {
    width: 0.25,
    position: [0.27, 0.19, 0.015],
    rotationY: -0.28,
  });
  root.add(panel.object3D);

  let lampOn = true;
  let level = 1;
  let pressPulse = 0;

  function applyState() {
    panel.set('state', lampOn ? {
      text: 'ON',
      color: '#c8ffdb',
      backgroundColor: '#28553b',
    } : {
      text: 'OFF',
      color: '#d1d6db',
      backgroundColor: '#3a4046',
    });
    panel.set('hint', {
      text: lampOn
        ? 'Press the lamp to switch it off.'
        : 'Press the lamp to switch it on.',
    });

    powerMaterial.color.setHex(lampOn ? 0x53d790 : 0x59636a);
    powerMaterial.emissive.setHex(lampOn ? 0x36d67f : 0x20272b);
  }

  function toggleLamp() {
    lampOn = !lampOn;
    pressPulse = 1;
    applyState();
  }

  traits(shade, { onPress: toggleLamp });
  traits(arm, { onPress: toggleLamp });
  traits(base, { onPress: toggleLamp });
  traits(powerButton, { onPress: toggleLamp });

  return {
    root,
    update(time, delta) {
      const target = lampOn ? 1 : 0;
      level += (target - level) * (1 - Math.exp(-delta * 12));
      if (Math.abs(target - level) < 0.001) level = target;

      bulbMaterial.emissiveIntensity = 0.03 + level * 2.3;
      innerMaterial.emissiveIntensity = 0.03 + level * 0.9;
      powerMaterial.emissiveIntensity = 0.03 + level * 1.2;

      beamMaterial.opacity = level * 0.055;
      haloMaterial.opacity = level * 0.14;
      poolOuterMaterial.opacity = level * 0.12;
      poolInnerMaterial.opacity = level * 0.18;

      const glowVisible = level > 0.005;
      beam.visible = glowVisible;
      halo.visible = glowVisible;
      poolOuter.visible = glowVisible;
      poolInner.visible = glowVisible;

      pressPulse = Math.max(0, pressPulse - delta * 7);
      powerButton.position.y = 0.038 - pressPulse * 0.004;
      powerButton.scale.y = 1 - pressPulse * 0.3;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const centerX = -0.15;
  const centerY = 0.17;

  const layerData = [
    {
      name: 'Crust',
      inner: 0.123,
      outer: 0.135,
      color: 0x83a95c,
      css: '#83a95c',
      selectedBg: '#31402b',
      subtitle: '5–70 km thick • solid',
      fact: 'A thin, solid rocky shell. Oceanic crust is 5–10 km thick; continental crust is usually 30–70 km thick.',
    },
    {
      name: 'Mantle',
      inner: 0.073,
      outer: 0.123,
      color: 0xd85d44,
      css: '#d85d44',
      selectedBg: '#49302c',
      subtitle: 'Extends to 2,890 km deep',
      fact: 'The thickest layer. Its mostly solid rock flows very slowly over geological time, helping move Earth’s tectonic plates.',
    },
    {
      name: 'Outer core',
      inner: 0.026,
      outer: 0.073,
      color: 0xf2a63b,
      css: '#f2a63b',
      selectedBg: '#4b3c25',
      subtitle: '2,890–5,150 km • liquid',
      fact: 'A liquid iron–nickel layer. Moving electrically conductive metal here drives the geodynamo that generates Earth’s magnetic field.',
    },
    {
      name: 'Inner core',
      inner: 0,
      outer: 0.026,
      color: 0xffdf80,
      css: '#ffdf80',
      selectedBg: '#4b432c',
      subtitle: '5,150–6,371 km • solid',
      fact: 'A solid iron–nickel sphere with a radius of about 1,220 km. Immense pressure keeps it solid despite its extremely high temperature.',
    },
  ];

  const layers = [];
  const cutStart = -Math.PI / 2;
  const cutLength = Math.PI;

  for (let i = 0; i < layerData.length; i++) {
    const data = layerData[i];
    const group = new THREE.Group();
    group.name = data.name;
    group.position.set(centerX, centerY, 0);
    root.add(group);

    const material = new THREE.MeshStandardMaterial({
      color: data.color,
      emissive: data.color,
      emissiveIntensity: 0.035,
      roughness: i >= 2 ? 0.48 : 0.7,
      metalness: i >= 2 ? 0.28 : 0.04,
      side: THREE.DoubleSide,
    });

    // Three quarters of each sphere remain, revealing two radial cut faces.
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(data.outer, 32, 16, Math.PI, Math.PI * 1.5),
      material,
    );
    sphere.name = `${data.name} curved surface`;
    group.add(sphere);

    const cutGeometry = data.inner === 0
      ? new THREE.CircleGeometry(data.outer, 48, cutStart, cutLength)
      : new THREE.RingGeometry(data.inner, data.outer, 48, 1, cutStart, cutLength);

    // Front-facing half-section on the z = 0 plane.
    const cutFront = new THREE.Mesh(cutGeometry, material);
    cutFront.name = `${data.name} front cut face`;
    cutFront.position.z = 0.0002;
    group.add(cutFront);

    // The second exposed half-section, on the x = 0 plane.
    const cutSide = new THREE.Mesh(cutGeometry, material);
    cutSide.name = `${data.name} side cut face`;
    cutSide.rotation.y = -Math.PI / 2;
    cutSide.position.x = -0.0002;
    group.add(cutSide);

    layers.push({ group, material, data });
  }

  const base = new THREE.Mesh(
    new THREE.CylinderGeometry(0.15, 0.16, 0.03, 48),
    new THREE.MeshStandardMaterial({
      color: 0x252b32,
      roughness: 0.5,
      metalness: 0.45,
    }),
  );
  base.name = 'Earth model stand';
  base.position.set(centerX, 0.015, 0);
  root.add(base);

  const panel = ui(`
    <style>
      .card {
        display: flex;
        flex-direction: column;
        gap: 10px;
        width: 450px;
        padding-top: 20px;
        padding-bottom: 20px;
        padding-left: 22px;
        padding-right: 22px;
        border-radius: 18px;
        border-width: 1px;
        border-color: #3a414b;
        background-color: #1a1d22;
      }
      .title {
        color: #ffffff;
        font-size: 30px;
        font-weight: 700;
      }
      .subtitle {
        color: #b9c2cf;
        font-size: 19px;
      }
      .layer {
        display: flex;
        flex-direction: row;
        align-items: center;
        gap: 14px;
        width: 450px;
        padding-top: 10px;
        padding-bottom: 10px;
        padding-left: 14px;
        padding-right: 14px;
        border-radius: 13px;
        border-width: 1px;
        border-color: #3a414b;
        background-color: #262b32;
      }
      .swatch {
        width: 22px;
        height: 22px;
        border-radius: 11px;
      }
      .crust-swatch { background-color: #83a95c; }
      .mantle-swatch { background-color: #d85d44; }
      .outer-swatch { background-color: #f2a63b; }
      .inner-swatch { background-color: #ffdf80; }
      .layer-copy {
        display: flex;
        flex-direction: column;
        gap: 2px;
      }
      .layer-name {
        color: #ffffff;
        font-size: 23px;
        font-weight: 700;
        text-align: left;
      }
      .layer-sub {
        color: #c4ccd6;
        font-size: 18px;
        text-align: left;
      }
      .detail {
        display: flex;
        flex-direction: column;
        gap: 7px;
        width: 450px;
        padding-top: 13px;
        padding-bottom: 13px;
        padding-left: 15px;
        padding-right: 15px;
        border-radius: 13px;
        background-color: #22272e;
      }
      .detail-title {
        color: #ffffff;
        font-size: 23px;
        font-weight: 700;
      }
      .detail-copy {
        color: #d4dbe4;
        font-size: 19px;
      }
      .reset {
        width: 450px;
        padding-top: 10px;
        padding-bottom: 10px;
        padding-left: 14px;
        padding-right: 14px;
        border-radius: 12px;
        border-width: 1px;
        border-color: #527cac;
        background-color: #294a6b;
      }
      .reset-text {
        color: #ffffff;
        font-size: 20px;
        font-weight: 700;
        text-align: center;
      }
    </style>
    <div class="card">
      <span class="title">Earth’s layers</span>
      <span class="subtitle">Press a layer or label • pinch to pull it out</span>

      <button class="layer" id="pick-crust">
        <div class="swatch crust-swatch"></div>
        <div class="layer-copy">
          <span class="layer-name">Crust</span>
          <span class="layer-sub">5–70 km thick • solid</span>
        </div>
      </button>

      <button class="layer" id="pick-mantle">
        <div class="swatch mantle-swatch"></div>
        <div class="layer-copy">
          <span class="layer-name">Mantle</span>
          <span class="layer-sub">Extends to 2,890 km deep</span>
        </div>
      </button>

      <button class="layer" id="pick-outer">
        <div class="swatch outer-swatch"></div>
        <div class="layer-copy">
          <span class="layer-name">Outer core</span>
          <span class="layer-sub">2,890–5,150 km • liquid</span>
        </div>
      </button>

      <button class="layer" id="pick-inner">
        <div class="swatch inner-swatch"></div>
        <div class="layer-copy">
          <span class="layer-name">Inner core</span>
          <span class="layer-sub">5,150–6,371 km • solid</span>
        </div>
      </button>

      <div class="detail">
        <span class="detail-title" id="detail-title">Crust</span>
        <span class="detail-copy" id="detail-copy"></span>
      </div>
      <span class="subtitle">Layer thicknesses are exaggerated; model is not to scale.</span>
      <button class="reset" id="reset"><span class="reset-text">Reassemble Earth</span></button>
    </div>
  `, {
    width: 0.3,
    position: [0.24, 0.19, 0.02],
    rotationY: -0.2,
  });
  root.add(panel.object3D);

  const buttonIds = ['pick-crust', 'pick-mantle', 'pick-outer', 'pick-inner'];
  let selected = 0;

  function selectLayer(index) {
    selected = index;
    panel.set('detail-title', { text: layerData[index].name });
    panel.set('detail-copy', { text: layerData[index].fact });

    for (let i = 0; i < buttonIds.length; i++) {
      panel.set(buttonIds[i], {
        backgroundColor: i === index ? layerData[i].selectedBg : '#262b32',
        borderColor: i === index ? layerData[i].css : '#3a414b',
      });
    }
  }

  function resetLayers() {
    for (let i = 0; i < layers.length; i++) {
      layers[i].group.position.set(centerX, centerY, 0);
    }
  }

  for (let i = 0; i < layers.length; i++) {
    traits(layers[i].group, {
      grab: true,
      onPress: () => selectLayer(i),
    });
    panel.on(buttonIds[i], 'click', () => selectLayer(i));
  }

  panel.on('reset', 'click', resetLayers);
  traits(base, { onPress: resetLayers });
  selectLayer(0);

  return {
    root,
    update(time) {
      for (let i = 0; i < layers.length; i++) {
        const held = isGrabbed(layers[i].group);
        layers[i].material.emissiveIntensity = held
          ? 0.24
          : i === selected
            ? 0.14 + Math.sin(time * 3) * 0.045
            : 0.035;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const colors = {
    light: 0xffd34d,
    water: 0x37b9ff,
    carbon: 0xb7c2d0,
    oxygen: 0x55e6a5,
  };

  // Sun: press it to learn where the energy comes from.
  const sunGroup = new THREE.Group();
  sunGroup.name = 'Sun';
  sunGroup.position.set(-0.27, 0.365, -0.045);
  root.add(sunGroup);

  const sun = new THREE.Mesh(
    new THREE.SphereGeometry(0.052, 28, 16),
    new THREE.MeshStandardMaterial({
      color: 0xffd34d,
      emissive: 0xff9d18,
      emissiveIntensity: 0.85,
      roughness: 0.55,
    }),
  );
  sun.name = 'Sun';
  sunGroup.add(sun);

  const rayGeometry = new THREE.ConeGeometry(0.008, 0.025, 6);
  const rayMaterial = new THREE.MeshStandardMaterial({
    color: 0xffd968,
    emissive: 0xffa71a,
    emissiveIntensity: 0.45,
  });
  for (let i = 0; i < 10; i += 1) {
    const angle = (i / 10) * Math.PI * 2;
    const ray = new THREE.Mesh(rayGeometry, rayMaterial);
    ray.position.set(Math.cos(angle) * 0.069, Math.sin(angle) * 0.069, 0);
    ray.rotation.z = angle - Math.PI / 2;
    sunGroup.add(ray);
  }

  // Pot, soil and plant.
  const pot = new THREE.Mesh(
    new THREE.CylinderGeometry(0.057, 0.043, 0.068, 28),
    new THREE.MeshStandardMaterial({ color: 0xb86842, roughness: 0.85 }),
  );
  pot.name = 'Plant pot';
  pot.position.set(-0.055, 0.04, 0);
  root.add(pot);

  const rim = new THREE.Mesh(
    new THREE.CylinderGeometry(0.062, 0.062, 0.015, 28),
    new THREE.MeshStandardMaterial({ color: 0xd58055, roughness: 0.8 }),
  );
  rim.position.set(-0.055, 0.077, 0);
  root.add(rim);

  const soil = new THREE.Mesh(
    new THREE.CylinderGeometry(0.055, 0.055, 0.006, 28),
    new THREE.MeshStandardMaterial({ color: 0x493326, roughness: 1 }),
  );
  soil.name = 'Soil and absorbed water';
  soil.position.set(-0.055, 0.087, 0);
  root.add(soil);

  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0045, 0.006, 0.172, 12),
    new THREE.MeshStandardMaterial({ color: 0x45934b, roughness: 0.75 }),
  );
  stem.name = 'Stem';
  stem.position.set(-0.055, 0.171, 0);
  root.add(stem);

  const leafGeometry = new THREE.SphereGeometry(1, 24, 12);
  const leafMaterial = new THREE.MeshStandardMaterial({
    color: 0x54ad55,
    roughness: 0.62,
  });

  function makeLeaf(name, x, y, z, angle, scaleX) {
    const leaf = new THREE.Mesh(leafGeometry, leafMaterial);
    leaf.name = name;
    leaf.position.set(x, y, z);
    leaf.scale.set(scaleX, 0.023, 0.008);
    leaf.rotation.z = angle;
    root.add(leaf);
    return leaf;
  }

  const leafLeft = makeLeaf('Leaf - lower left', -0.103, 0.163, 0.003, -0.42, 0.061);
  const leafRight = makeLeaf('Leaf - lower right', -0.008, 0.191, 0.006, 0.48, 0.062);
  const leafUpperLeft = makeLeaf('Leaf - upper left', -0.104, 0.239, 0, 0.5, 0.064);
  const leafUpperRight = makeLeaf('Leaf - upper right', -0.006, 0.271, -0.002, -0.38, 0.061);
  makeLeaf('Leaf - top', -0.054, 0.284, 0, Math.PI / 2, 0.047);

  // Arrows: light and carbon dioxide enter; water rises; oxygen exits.
  function makeArrow(name, start, end, color, radius) {
    const direction = new THREE.Vector3().subVectors(end, start);
