        color: #ffffff;
        font-size: 30px;
        font-weight: 700;
      }
      .instruction {
        color: #bdc7d3;
        font-size: 20px;
      }
      .layer {
        width: 472px;
        flex-direction: row;
        align-items: center;
        gap: 12px;
        padding-top: 8px;
        padding-bottom: 8px;
        padding-left: 12px;
        padding-right: 12px;
