      }
      .crust-color { background-color: #b49a68; }
      .mantle-color { background-color: #d85b32; }
      .outer-color { background-color: #f2a33b; }
      .inner-color { background-color: #ffdc78; }
      .layer-copy {
        flex-direction: column;
        gap: 2px;
      }
      .layer-name {
        color: #ffffff;
        font-size: 22px;
        font-weight: 700;
      }
      .layer-range {
        color: #c4cdd7;
        font-size: 18px;
      }
      .detail {
        width: 472px;
        flex-direction: column;
        gap: 6px;
        padding-top: 12px;
        padding-bottom: 12px;
        padding-left: 12px;
        padding-right: 12px;
        border-radius: 12px;
        background-color: #252b33;
      }
      .detail-title {
        color: #ffffff;
        font-size: 23px;
        font-weight: 700;
      }
