        padding-bottom: 9px;
        padding-left: 12px;
        padding-right: 12px;
        border-radius: 12px;
        background-color: #356da5;
      }
      .reset-text {
        color: #ffffff;
        font-size: 20px;
        font-weight: 700;
        text-align: center;
      }
      .note {
        color: #9eabb9;
        font-size: 18px;
      }
    </style>
    <div class="card">
      <span class="title">Layers of the Earth</span>
      <span class="instruction">Press a label or layer. Pinch-drag a layer to pull it out.</span>

      <button class="layer" id="layer-crust">
        <span class="swatch crust-color"></span>
        <div class="layer-copy">
          <span class="layer-name">Crust</span>
          <span class="layer-range">Solid rock · about 5–70 km thick</span>
