  addSphere(londonIcon, cloudMaterial, 0.019, 0, 0, 0.019, 0.016, 0.012, 'London cloud right');

  const rainDrops = [];
  const rainX = [-0.024, -0.012, 0, 0.012, 0.024];
  for (let i = 0; i < rainX.length; i++) {
    const drop = addSphere(
      londonIcon, rainMaterial, rainX[i], -0.026 - i * 0.005, 0.008,
      0.0035, 0.007, 0.0035, 'Raindrop ' + (i + 1),
    );
    rainDrops.push({ mesh: drop, phase: i * 0.0064 });
  }

  const newYorkIcon = makeIcon('New York partly cloudy icon', 0.211, 0.405);
  addSphere(newYorkIcon, sunMaterial, -0.014, 0.014, -0.006, 0.018, 0.018, 0.018, 'New York sun');
  const newYorkSun = new THREE.Group();
  newYorkSun.position.set(-0.014, 0.014, -0.006);
  newYorkIcon.add(newYorkSun);
  const newYorkRays = addRays(newYorkSun, 8, 0.029, 0.7);
  addSphere(newYorkIcon, brightCloudMaterial, -0.009, -0.004, 0.009, 0.019, 0.015, 0.012, 'New York cloud left');
  addSphere(newYorkIcon, brightCloudMaterial, 0.007, 0.003, 0.01, 0.02, 0.021, 0.013, 'New York cloud center');
  addSphere(newYorkIcon, brightCloudMaterial, 0.024, -0.005, 0.009, 0.016, 0.014, 0.011, 'New York cloud right');

  const icons = [tokyoIcon, londonIcon, newYorkIcon];
  let selected = 0;
  let unit = 'C';

  function temperature(celsius) {
    const value = unit === 'C' ? celsius : celsius * 9 / 5 + 32;
    return Math.round(value) + '°';
  }

  function selectCity(index) {
    selected = index;
    for (let i = 0; i < cities.length; i++) {
      panel.set(cities[i].id + 'Card', {
        backgroundColor: i === selected ? '#2d4962' : '#242932',
      });
    }
    const city = cities[index];
    panel.set('detailTitle', { text: city.name + ' · ' + city.condition });
    panel.set('detailBody', {
      text: 'Feels like ' + temperature(city.feels) +
        ' · Humidity ' + city.humidity + '% · Wind ' + city.wind,
    });
  }

  function updateTemperatures() {
    for (let i = 0; i < cities.length; i++) {
      const city = cities[i];
      panel.set(city.id + 'Temp', { text: temperature(city.temp) });
      panel.set(city.id + 'Range', {
        text: 'H ' + temperature(city.high) + '  L ' + temperature(city.low),
      });
    }
    selectCity(selected);
  }

  for (let i = 0; i < cities.length; i++) {
    panel.on(cities[i].id + 'Card', 'click', () => selectCity(i));
    traits(icons[i], { onPress: () => selectCity(i) });
  }

  panel.on('unit', 'click', () => {
    unit = unit === 'C' ? 'F' : 'C';
    panel.set('unitLabel', { text: unit === 'C' ? '°C' : '°F' });
    updateTemperatures();
  });

  selectCity(0);

  return {
    root,
    update(time, delta) {
      tokyoRays.rotation.z = time * 0.18;
      newYorkRays.rotation.z = -time * 0.12;

      for (let i = 0; i < rainDrops.length; i++) {
        const drop = rainDrops[i];
        drop.mesh.position.y = -0.024 - ((time * 0.03 + drop.phase) % 0.032);
      }

      const blend = Math.min(1, delta * 8);
      for (let i = 0; i < icons.length; i++) {
        const targetScale = i === selected ? 1.07 : 1;
        const scale = icons[i].scale.x + (targetScale - icons[i].scale.x) * blend;
        icons[i].scale.setScalar(scale);
      }
    },
  };
}

