  const stemStart = new THREE.Vector3(-0.025, 0.082, 0);
  const stemEnd = new THREE.Vector3(-0.027, 0.282, 0);
  const stemDirection = new THREE.Vector3().subVectors(stemEnd, stemStart);
  const stemLength = stemDirection.length();
  stem.position.copy(stemStart).add(stemEnd).multiplyScalar(0.5);
  stem.quaternion.setFromUnitVectors(Y_AXIS, stemDirection.normalize());
  stem.scale.set(0.0075, stemLength, 0.0075);
  plant.add(stem);

  const leafGeometry = new THREE.SphereGeometry(1, 24, 12);
  const leafMaterial = new THREE.MeshStandardMaterial({
    color: 0x49a950,
    emissive: 0x164d20,
    emissiveIntensity: 0.16,
    roughness: 0.62,
  });
  const leaves = [];
  const leafData = [
    [-0.077, 0.153, 0.000, 0.050, 0.021, 0.009, 0.25],
    [ 0.018, 0.178, 0.002, 0.050, 0.021, 0.009, -0.32],
    [-0.082, 0.218, -0.004, 0.055, 0.023, 0.009, -0.30],
    [ 0.025, 0.240, -0.001, 0.056, 0.024, 0.009, 0.42],
    [-0.032, 0.286, 0.000, 0.036, 0.020, 0.008, 1.00],
  ];

  for (let i = 0; i < leafData.length; i++) {
    const d = leafData[i];
    const leaf = new THREE.Mesh(leafGeometry, leafMaterial);
    leaf.name = 'Leaf ' + (i + 1);
    leaf.position.set(d[0], d[1], d[2]);
    leaf.scale.set(d[3], d[4], d[5]);
    leaf.rotation.z = d[6];
    plant.add(leaf);
    leaves.push({ mesh: leaf, baseRotation: d[6], phase: i * 1.17 });
  }

  // The Sun, with slowly rotating rays.
  const sun = new THREE.Group();
  sun.name = 'Sun';
  sun.position.set(-0.275, 0.362, -0.04);
  root.add(sun);

  const sunMaterial = new THREE.MeshStandardMaterial({
    color: 0xffd45c,
    emissive: 0xffa500,
    emissiveIntensity: 0.95,
    roughness: 0.5,
  });
  const sunSphere = new THREE.Mesh(
    new THREE.SphereGeometry(0.049, 28, 16),
    sunMaterial,
  );
  sunSphere.name = 'Sun sphere';
  sun.add(sunSphere);

  const rays = new THREE.Group();
  const rayGeometry = new THREE.BoxGeometry(0.009, 0.028, 0.009);
  const rayMaterial = new THREE.MeshBasicMaterial({ color: 0xffcf52 });
  for (let i = 0; i < 10; i++) {
    const angle = (i / 10) * Math.PI * 2;
    const ray = new THREE.Mesh(rayGeometry, rayMaterial);
    ray.position.set(Math.cos(angle) * 0.069, Math.sin(angle) * 0.069, 0);
    ray.rotation.z = angle - Math.PI / 2;
    rays.add(ray);
  }
  sun.add(rays);

  let activeKey = null;
  let flowRunning = true;
  let flowTime = 0;
  let nextIndex = 0;
  const sequence = ['light', 'water', 'co2', 'oxygen', 'leaf'];

  const details = {
    light: {
      color: '#ffe078',
      text: 'Light energy: Chlorophyll in chloroplasts captures light energy. This powers the reactions that make glucose.',
    },
    water: {
      color: '#79cfff',
      text: 'Water: Roots absorb water from the soil. Xylem vessels carry it up the stem to the leaves.',
    },
    co2: {
      color: '#d2d9e4',
      text: 'Carbon dioxide: CO₂ enters through tiny leaf pores called stomata. Its carbon atoms become part of glucose.',
    },
    oxygen: {
      color: '#83f0df',
      text: 'Oxygen: O₂ exits through stomata. It is released when water molecules are split during the light-dependent reactions.',
    },
    leaf: {
      color: '#a9eaa5',
      text: 'Inside the leaf: Chloroplasts make glucose, which stores chemical energy. The plant uses it for respiration and growth.',
    },
  };

  const info = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 9px; width: 560px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px;
              border-radius: 18px; border-width: 2px; border-color: #405346;
              background-color: #1c2329; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .detail { color: #d9e0e8; font-size: 22px; text-align: left; }
      .equation { color: #b9dcc3; font-size: 20px; font-weight: 700; text-align: center; }
      .row { display: flex; flex-direction: row; justify-content: center; gap: 10px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #356247; }
      .next { background-color: #344c63; }
      .btnText { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Photosynthesis</span>
      <span class="detail" id="detail">Press a colored label or arrow, or choose Next step. Moving dots show energy and matter flowing.</span>
      <span class="equation">Overall: 6CO₂ + 6H₂O + light energy → C₆H₁₂O₆ (glucose) + 6O₂</span>
      <div class="row">
        <button class="btn" id="flow"><span class="btnText" id="flowText">Pause flow</span></button>
        <button class="btn next" id="next"><span class="btnText">Next step</span></button>
      </div>
    </div>`, { width: 0.35, position: [0, 0.397, 0.15] });
  info.object3D.name = 'Photosynthesis explanation';
  root.add(info.object3D);

  function select(key) {
    const item = details[key];
    activeKey = key;
    info.set('detail', { text: item.text, color: item.color });
    const index = sequence.indexOf(key);
    if (index >= 0) nextIndex = (index + 1) % sequence.length;
  }

  info.on('flow', 'click', () => {
    flowRunning = !flowRunning;
    info.set('flowText', { text: flowRunning ? 'Pause flow' : 'Resume flow' });
  });
  info.on('next', 'click', () => select(sequence[nextIndex]));

  traits(plant, { onPress: () => select('leaf') });
  traits(sun, { onPress: () => select('light') });

  const arrows = [];

  function makeArrow(key, name, startArray, endArray, color) {
    const start = new THREE.Vector3(startArray[0], startArray[1], startArray[2]);
    const end = new THREE.Vector3(endArray[0], endArray[1], endArray[2]);
    const direction = new THREE.Vector3().subVectors(end, start);
    const length = direction.length();

    const group = new THREE.Group();
    group.name = name;
    group.position.copy(start);
    group.quaternion.setFromUnitVectors(Y_AXIS, direction.normalize());

    const material = new THREE.MeshStandardMaterial({
      color,
      emissive: color,
      emissiveIntensity: 0.3,
      roughness: 0.45,
    });

    const headLength = 0.035;
    const shaftLength = length - headLength;
    const shaft = new THREE.Mesh(unitCylinder, material);
    shaft.scale.set(0.0065, shaftLength, 0.0065);
    shaft.position.y = shaftLength / 2;
    group.add(shaft);

    const head = new THREE.Mesh(unitCone, material);
    head.scale.set(0.017, headLength, 0.017);
    head.position.y = shaftLength + headLength / 2;
    group.add(head);

    // A larger invisible target makes the whole arrow easy to poke or pinch.
    const hit = new THREE.Mesh(unitCylinder, hitMaterial);
    hit.scale.set(0.022, length, 0.022);
    hit.position.y = length / 2;
    group.add(hit);

    const particles = [];
    for (let i = 0; i < 3; i++) {
      const particle = new THREE.Mesh(particleGeometry, material);
      particle.position.y = (i + 0.5) * length / 3;
      group.add(particle);
      particles.push(particle);
    }

    root.add(group);
    traits(group, { onPress: () => select(key) });
    arrows.push({ key, group, material, particles, length });
    return group;
  }

  makeArrow(
    'light',
    'Light energy arrow',
    [-0.225, 0.320, -0.025],
    [-0.085, 0.239, 0.005],
    0xffcf4a,
  );
  makeArrow(
    'water',
    'Water arrow',
    [-0.275, 0.025, 0.045],
    [-0.073, 0.087, 0.024],
    0x38a9ed,
  );
  makeArrow(
    'co2',
    'Carbon dioxide arrow',
    [0.300, 0.207, 0.030],
    [0.050, 0.186, 0.010],
    0xafbccc,
  );
  makeArrow(
    'oxygen',
    'Oxygen arrow',
    [0.058, 0.255, 0.008],
    [0.292, 0.374, 0.024],
    0x52d9c8,
  );

  function makeTag(key, label, position, width, cssColor) {
    const tag = ui(`
      <style>
        .tag { display: flex; width: 360px; }
        .tagButton { display: flex; align-items: center; justify-content: center;
                     padding-top: 9px; padding-bottom: 9px; padding-left: 14px; padding-right: 14px;
                     border-radius: 14px; border-width: 3px; border-color: ${cssColor};
                     background-color: #20262c; }
        .tagText { color: ${cssColor}; font-size: 25px; font-weight: 700; text-align: center; }
      </style>
      <div class="tag">
        <button class="tagButton" id="tag"><span class="tagText">${label}</span></button>
      </div>`, { width, position });
    tag.object3D.name = label + ' label';
    root.add(tag.object3D);
    tag.on('tag', 'click', () => select(key));
  }

  makeTag('light', 'Light energy', [-0.220, 0.225, 0.085], 0.160, '#ffe078');
  makeTag('water', 'Water (H₂O)', [-0.215, 0.105, 0.090], 0.165, '#79cfff');
  makeTag('co2', 'Carbon dioxide (CO₂)', [0.260, 0.158, 0.080], 0.180, '#d2d9e4');
  makeTag('oxygen', 'Oxygen (O₂)', [0.265, 0.416, 0.090], 0.160, '#83f0df');

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);
      if (flowRunning) flowTime += dt;

      rays.rotation.z = time * 0.035;
      sunMaterial.emissiveIntensity = 0.95 + Math.sin(time * 1.4) * 0.12;
      leafMaterial.emissiveIntensity = activeKey === 'leaf'
        ? 0.55 + Math.sin(time * 3) * 0.15
        : 0.16;

      for (let i = 0; i < leaves.length; i++) {
        const leaf = leaves[i];
        leaf.mesh.rotation.z = leaf.baseRotation + Math.sin(time * 0.9 + leaf.phase) * 0.025;
      }

      for (let i = 0; i < arrows.length; i++) {
        const arrow = arrows[i];
        const selected = activeKey === arrow.key;
        arrow.material.emissiveIntensity = selected
          ? 0.85 + Math.sin(time * 3.2) * 0.18
          : 0.28 + Math.sin(flowTime * 2 + i) * 0.06;

        for (let j = 0; j < arrow.particles.length; j++) {
          const phase = (flowTime * 0.22 + j / 3) % 1;
          arrow.particles[j].position.y = 0.010 + phase * (arrow.length - 0.020);
        }
      }
    },
  };
}

