        font-weight: 700;
      }
      .row-label {
        width: 116px;
        margin-right: 6px;
        color: #8f9aa8;
        font-size: 17px;
      }
      .day-heading {
        width: 42px;
        height: 24px;
        text-align: center;
        color: #9faab7;
        font-size: 16px;
        font-weight: 700;
      }
      .streak-heading {
        width: 64px;
        margin-left: 6px;
        text-align: right;
        color: #9faab7;
        font-size: 17px;
