        padding-left: 0px;
        padding-right: 0px;
        border-radius: 10px;
        border-width: 1px;
        border-color: #4a5563;
        background-color: #303843;
      }
      .day-mark {
        color: #818c99;
        font-size: 25px;
        font-weight: 700;
        text-align: center;
      }
      .streak {
        width: 64px;
        margin-left: 6px;
        text-align: right;
        color: #ffffff;
        font-size: 19px;
        font-weight: 700;
      }
      .footer {
        color: #8f9aa8;
        font-size: 17px;
      }
    </style>
    <div class="panel">
      <div class="top">
        <span class="title">This week's habits</span>
        <span class="total" id="total">0 / 21 done</span>
