      }
      .habitGoal {
        color: #aeb7c2;
        font-size: 20px;
      }
      .streak {
        color: #97a3b2;
        font-size: 20px;
        font-weight: 700;
      }
      .dayButton {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 48px;
        height: 46px;
        border-radius: 12px;
        border-width: 2px;
        border-color: #3a424d;
        background-color: #2a2e35;
      }
      .dayMark {
        color: #8e99a8;
        font-size: 25px;
        font-weight: 700;
        text-align: center;
      }
      .footer {
        display: flex;
        flex-direction: row;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        width: 524px;
        padding-top: 4px;
        padding-bottom: 0px;
        padding-left: 0px;
        padding-right: 0px;
      }
      .progress {
        color: #d7dce3;
        font-size: 20px;
        font-weight: 700;
      }
      .clearButton {
        padding-top: 9px;
        padding-bottom: 9px;
        padding-left: 16px;
        padding-right: 16px;
        border-radius: 11px;
        border-width: 1px;
        border-color: #4a5562;
        background-color: #343b45;
