  addBox('Basket base', darkWicker, 0.25, 0.024, 0.19, 0, 0.012, 0);

  [0.041, 0.073, 0.105].forEach((y, index) => {
    addBox(`Front slat ${index + 1}`, wicker, 0.24, 0.02, 0.014, 0, y, 0.09);
    addBox(`Back slat ${index + 1}`, wicker, 0.24, 0.02, 0.014, 0, y, -0.09);
    addBox(`Left slat ${index + 1}`, wicker, 0.014, 0.02, 0.18, -0.12, y, 0);
    addBox(`Right slat ${index + 1}`, wicker, 0.014, 0.02, 0.18, 0.12, y, 0);
  });

  [-0.112, 0.112].forEach((x) => {
    [-0.082, 0.082].forEach((z) => {
      addBox('Basket corner post', darkWicker, 0.018, 0.126, 0.018, x, 0.063, z);
    });
  });

  const handleGeometry = new THREE.TorusGeometry(0.037, 0.005, 8, 20, Math.PI);
  [-0.126, 0.126].forEach((x) => {
    const handle = new THREE.Mesh(handleGeometry, darkWicker);
    handle.name = 'Basket side handle';
    handle.position.set(x, 0.108, 0);
