  dropRing.name = 'Basket drop zone';
  dropRing.rotation.x = -Math.PI / 2;
  dropRing.scale.x = 1.45;
  dropRing.position.y = 0.026;
  basket.add(dropRing);

  const stemGeometry = new THREE.CylinderGeometry(0.0035, 0.0045, 0.02, 8);
  const leafGeometry = new THREE.SphereGeometry(0.012, 12, 8);
  const fruitSphere = new THREE.SphereGeometry(0.04, 24, 16);
  const stemMaterial = new THREE.MeshStandardMaterial({ color: 0x5d3a20, roughness: 0.9 });
  const leafMaterial = new THREE.MeshStandardMaterial({ color: 0x3d8b43, roughness: 0.8 });

  function makeApple() {
    const group = new THREE.Group();
    group.name = 'Apple';

    const body = new THREE.Mesh(
      fruitSphere,
      new THREE.MeshStandardMaterial({ color: 0xd94242, roughness: 0.55 }),
    );
    body.name = 'Apple body';
    body.scale.y = 0.9;
    group.add(body);

    const stem = new THREE.Mesh(stemGeometry, stemMaterial);
    stem.position.y = 0.045;
    stem.rotation.z = -0.12;
    group.add(stem);

    const leaf = new THREE.Mesh(leafGeometry, leafMaterial);
    leaf.scale.set(1.45, 0.25, 0.65);
    leaf.position.set(0.013, 0.049, 0);
    leaf.rotation.z = -0.5;
    group.add(leaf);
    return group;
  }

  function makeOrange() {
    const group = new THREE.Group();
    group.name = 'Orange';

    const body = new THREE.Mesh(
      fruitSphere,
      new THREE.MeshStandardMaterial({ color: 0xf28c1e, roughness: 0.78 }),
    );
    body.name = 'Orange body';
    body.scale.setScalar(0.95);
    group.add(body);

    const stem = new THREE.Mesh(stemGeometry, stemMaterial);
    stem.scale.set(0.8, 0.45, 0.8);
    stem.position.y = 0.04;
    group.add(stem);

    const leaf = new THREE.Mesh(leafGeometry, leafMaterial);
    leaf.scale.set(0.9, 0.2, 0.5);
    leaf.position.set(0.009, 0.043, 0);
    leaf.rotation.z = -0.45;
    group.add(leaf);
    return group;
  }

  function makeBanana() {
    const group = new THREE.Group();
    group.name = 'Banana';

    const curve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(-0.055, -0.008, 0),
      new THREE.Vector3(-0.035, 0.012, 0),
      new THREE.Vector3(0, 0.023, 0),
      new THREE.Vector3(0.035, 0.012, 0),
      new THREE.Vector3(0.055, -0.008, 0),
    ]);
    const body = new THREE.Mesh(
      new THREE.TubeGeometry(curve, 20, 0.013, 8, false),
      new THREE.MeshStandardMaterial({ color: 0xf2cf3c, roughness: 0.65 }),
    );
    body.name = 'Banana body';
    group.add(body);

    const tipGeometry = new THREE.SphereGeometry(0.014, 12, 8);
    const tipMaterial = new THREE.MeshStandardMaterial({ color: 0x705126, roughness: 0.9 });
