    const bananaMaterial = new THREE.MeshStandardMaterial({ color: 0xf4cf45, roughness: 0.7 });
    const body = new THREE.Mesh(new THREE.TubeGeometry(curve, 24, 0.010, 8, false), bananaMaterial);
    body.name = 'BananaBody';
    group.add(body);

    const leftCap = new THREE.Mesh(smallSphereGeometry, bananaMaterial);
    leftCap.scale.setScalar(0.0105);
    leftCap.position.set(-0.045, 0.004, -0.008);
    group.add(leftCap);

    const rightCap = new THREE.Mesh(smallSphereGeometry, bananaMaterial);
    rightCap.scale.setScalar(0.0105);
    rightCap.position.set(0.045, 0.004, -0.008);
    group.add(rightCap);

    const tipMaterial = new THREE.MeshStandardMaterial({ color: 0x74502b, roughness: 0.9 });
    const leftTip = new THREE.Mesh(smallSphereGeometry, tipMaterial);
    leftTip.scale.setScalar(0.004);
    leftTip.position.set(-0.052, 0.005, -0.009);
    group.add(leftTip);

    const rightTip = new THREE.Mesh(smallSphereGeometry, tipMaterial);
    rightTip.scale.setScalar(0.004);
    rightTip.position.set(0.052, 0.005, -0.009);
    group.add(rightTip);

    return group;
  }

  // An open, low-sided basket keeps its contents visible and easy to pinch.
  const basket = new THREE.Group();
  basket.name = 'Basket';
  basket.position.set(0.19, 0, -0.015);
  root.add(basket);

  const baseMaterial = new THREE.MeshStandardMaterial({ color: 0x795033, roughness: 0.9 });
  const wallMaterial = new THREE.MeshStandardMaterial({ color: 0xa97847, roughness: 0.85 });
  const rimMaterial = new THREE.MeshStandardMaterial({
    color: 0xc39458,
    roughness: 0.75,
    emissive: 0x1a0d02,
    emissiveIntensity: 0.25,
  });

  const base = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.014, 0.18), baseMaterial);
  base.name = 'BasketBase';
  base.position.y = 0.007;
  basket.add(base);

  const frontBackWallGeometry = new THREE.BoxGeometry(0.22, 0.042, 0.012);
  const frontWall = new THREE.Mesh(frontBackWallGeometry, wallMaterial);
  frontWall.position.set(0, 0.035, 0.084);
  basket.add(frontWall);

  const backWall = new THREE.Mesh(frontBackWallGeometry, wallMaterial);
  backWall.position.set(0, 0.035, -0.084);
  basket.add(backWall);

  const sideWallGeometry = new THREE.BoxGeometry(0.012, 0.042, 0.156);
  const leftWall = new THREE.Mesh(sideWallGeometry, wallMaterial);
  leftWall.position.set(-0.104, 0.035, 0);
  basket.add(leftWall);

  const rightWall = new THREE.Mesh(sideWallGeometry, wallMaterial);
  rightWall.position.set(0.104, 0.035, 0);
  basket.add(rightWall);

  const longRimGeometry = new THREE.BoxGeometry(0.232, 0.010, 0.016);
  const frontRim = new THREE.Mesh(longRimGeometry, rimMaterial);
  frontRim.position.set(0, 0.066, 0.087);
  basket.add(frontRim);

  const backRim = new THREE.Mesh(longRimGeometry, rimMaterial);
  backRim.position.set(0, 0.066, -0.087);
  basket.add(backRim);

  const sideRimGeometry = new THREE.BoxGeometry(0.016, 0.010, 0.176);
  const leftRim = new THREE.Mesh(sideRimGeometry, rimMaterial);
  leftRim.position.set(-0.108, 0.066, 0);
  basket.add(leftRim);

  const rightRim = new THREE.Mesh(sideRimGeometry, rimMaterial);
  rightRim.position.set(0.108, 0.066, 0);
  basket.add(rightRim);

  const info = ui(`
    <style>
      .card { display: flex; flex-direction: column; width: 460px; gap: 9px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px;
