      .total-row { display: flex; flex-direction: row; justify-content: space-between; gap: 16px;
                   padding-top: 9px; padding-bottom: 9px; border-color: #59616d; border-width: 1px;
                   border-radius: 10px; background-color: #2a2e35; }
