      .total { color: #8ee08a; font-size: 26px; font-weight: 700; }
      .contents { color: #c9d0d9; font-size: 20px; }
      .button { display: flex; align-items: center; justify-content: center;
                padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
                border-radius: 12px; background-color: #3f5879; }
      .button-text { color: #ffffff; font-size: 21px; font-weight: 700; }
