  const dropMat = new THREE.MeshStandardMaterial({ color: 0x3a8dde, emissive: 0x124e8a, emissiveIntensity: 0.4, roughness: 0.3 });
  const snowMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0x9fcfff, emissiveIntensity: 0.25, roughness: 0.5 });
  const beamMat = new THREE.MeshBasicMaterial({ color: 0x7ec8ff, transparent: true, opacity: 0.35 });
  const dotMats = [
    new THREE.MeshStandardMaterial({ color: 0xff9f2e, emissive: 0x8a4d00, emissiveIntensity: 0.5, roughness: 0.5 }),
    new THREE.MeshStandardMaterial({ color: 0x3a8dde, emissive: 0x124e8a, emissiveIntensity: 0.5, roughness: 0.5 }),
    new THREE.MeshStandardMaterial({ color: 0xd6f2ff, emissive: 0x6fa8c8, emissiveIntensity: 0.5, roughness: 0.5 }),
  ];

  const platform = new THREE.Mesh(new THREE.BoxGeometry(0.64, 0.02, 0.22), platformMat);
  platform.name = 'DashboardBase';
  platform.position.set(0, 0.01, 0);
  root.add(platform);

  const pedestalGeo = new THREE.CylinderGeometry(0.065, 0.07, 0.02, 24);
  const beamGeo = new THREE.CylinderGeometry(0.003, 0.003, 0.09, 8);
  const dotGeo = new THREE.SphereGeometry(0.009, 16, 10);

  for (let i = 0; i < 3; i++) {
    const mat = new THREE.MeshStandardMaterial({ color: 0x2e3440, emissive: 0x000000, emissiveIntensity: 0, roughness: 0.6, metalness: 0.15 });
    pedestalMats.push(mat);
    const pedestal = new THREE.Mesh(pedestalGeo, mat);
    pedestal.name = cities[i].name + 'Pedestal';
    pedestal.position.set(cityX[i], 0.03, 0);
    root.add(pedestal);

    const beam = new THREE.Mesh(beamGeo, beamMat);
    beam.name = cities[i].name + 'Beam';
    beam.position.set(cityX[i], 0.085, -0.02);
    root.add(beam);

    const dot = new THREE.Mesh(dotGeo, dotMats[i]);
    dot.name = cities[i].name + 'Dot';
    dot.position.set(cityX[i], 0.029, 0.09);
    root.add(dot);
  }

  const cloudGeo = new THREE.SphereGeometry(0.027, 20, 14);
  function makeCloud(material, name) {
    const group = new THREE.Group();
    group.name = name;
    const puffs = [
      [0, 0, 0, 1.0],
      [-0.026, -0.004, 0, 0.78],
      [0.026, -0.004, 0, 0.84],
      [0, 0.013, 0.004, 0.72],
    ];
    for (let i = 0; i < puffs.length; i++) {
      const puff = new THREE.Mesh(cloudGeo, material);
      puff.name = 'CloudPuff';
      puff.position.set(puffs[i][0], puffs[i][1], puffs[i][2]);
      puff.scale.setScalar(puffs[i][3]);
      group.add(puff);
    }
    return group;
  }

  const phoenixIcon = new THREE.Group();
  phoenixIcon.name = 'PhoenixIcon';
  phoenixIcon.position.set(cityX[0], 0.14, 0);
  const sun = new THREE.Mesh(new THREE.SphereGeometry(0.033, 32, 16), sunMat);
  sun.name = 'Sun';
  phoenixIcon.add(sun);
  sunRays = new THREE.Group();
  sunRays.name = 'SunRays';
  const rayGeo = new THREE.ConeGeometry(0.008, 0.026, 8);
  for (let i = 0; i < 8; i++) {
    const angle = i * Math.PI / 4;
    const ray = new THREE.Mesh(rayGeo, sunMat);
    ray.name = 'SunRay';
    ray.position.set(Math.cos(angle) * 0.048, Math.sin(angle) * 0.048, 0);
    ray.rotation.z = angle - Math.PI / 2;
    sunRays.add(ray);
  }
  phoenixIcon.add(sunRays);
  root.add(phoenixIcon);
  icons.push(phoenixIcon);

  const londonIcon = new THREE.Group();
  londonIcon.name = 'LondonIcon';
  londonIcon.position.set(cityX[1], 0.14, 0);
  rainCloud = makeCloud(rainCloudMat, 'RainCloud');
  londonIcon.add(rainCloud);
  const dropGeo = new THREE.SphereGeometry(0.006, 10, 8);
  for (let i = 0; i < 5; i++) {
    const drop = new THREE.Mesh(dropGeo, dropMat);
    drop.name = 'Raindrop';
    const baseX = -0.03 + i * 0.015;
    drop.position.set(baseX, -0.03, 0);
    drop.scale.set(1, 1.9, 1);
    londonIcon.add(drop);
    rainDrops.push({ mesh: drop, baseX: baseX, phase: i * 0.011 });
  }
  root.add(londonIcon);
  icons.push(londonIcon);

  const chicagoIcon = new THREE.Group();
  chicagoIcon.name = 'ChicagoIcon';
  chicagoIcon.position.set(cityX[2], 0.14, 0);
  snowCloud = makeCloud(snowCloudMat, 'SnowCloud');
  chicagoIcon.add(snowCloud);
  const snowGeo = new THREE.SphereGeometry(0.0055, 10, 8);
  for (let i = 0; i < 6; i++) {
    const flake = new THREE.Mesh(snowGeo, snowMat);
    flake.name = 'Snowflake';
    const baseX = -0.03 + i * 0.012;
    flake.position.set(baseX, -0.03, 0);
    chicagoIcon.add(flake);
    snowFlakes.push({ mesh: flake, baseX: baseX, phase: i * 0.01 });
  }
  root.add(chicagoIcon);
  icons.push(chicagoIcon);

  const info = ui(`
    <style>
      .card { width: 500px; display: flex; flex-direction: column; align-items: center; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1a1d22; border-width: 2px; border-color: #3a4150; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; text-align: center; }
      .row { display: flex; flex-direction: row; justify-content: center; gap: 10px; }
      .city { display: flex; flex-direction: column; align-items: center; gap: 3px; width: 140px; padding-top: 9px; padding-bottom: 9px; padding-left: 8px; padding-right: 8px; border-radius: 14px; background-color: #262c36; border-width: 1px; border-color: #3a4150; }
      .city-name { color: #ffffff; font-size: 20px; font-weight: 700; text-align: center; }
      .temp { color: #ffffff; font-size: 31px; font-weight: 700; text-align: center; }
      .temp0 { color: #ffb84d; }
      .temp1 { color: #7ec8ff; }
      .temp2 { color: #d6f2ff; }
      .cond { color: #d7dbe2; font-size: 20px; text-align: center; }
      .detail { color: #d7dbe2; font-size: 22px; text-align: center; }
      .btn { display: flex; padding-top: 8px; padding-bottom: 8px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2f6fdb; border-width: 1px; border-color: #5a9bff; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">WEATHER DASHBOARD</span>
      <div class="row">
        <div class="city"><span class="city-name">PHOENIX</span><span class="temp temp0" id="temp0">34 C</span><span class="cond">Sunny</span></div>
        <div class="city"><span class="city-name">LONDON</span><span class="temp temp1" id="temp1">14 C</span><span class="cond">Rain</span></div>
        <div class="city"><span class="city-name">CHICAGO</span><span class="temp temp2" id="temp2">-2 C</span><span class="cond">Snow</span></div>
      </div>
      <span class="detail" id="detail">Press a 3D icon below for details.</span>
      <button class="btn" id="unit"><span class="btn-text" id="unit-text">Show Fahrenheit</span></button>
    </div>`, { width: 0.42, position: [0, 0.35, -0.09], rotationY: 0 });
  root.add(info.object3D);

  function formatTemp(c) {
    return useC ? c + ' C' : Math.round(c * 9 / 5 + 32) + ' F';
  }
  function detailFor(index) {
    const c = cities[index];
    return c.name + ': ' + c.condition + ', ' + formatTemp(c.tempC) + '. Humidity ' + c.humidity + '%, wind ' + c.wind + ' km/h.';
  }
  function renderTemps() {
    for (let i = 0; i < cities.length; i++) {
      info.set('temp' + i, { text: formatTemp(cities[i].tempC) });
    }
    info.set('unit-text', { text: useC ? 'Show Fahrenheit' : 'Show Celsius' });
    if (selected >= 0) {
      info.set('detail', { text: detailFor(selected) });
    }
  }
  function selectCity(index) {
    selected = index;
    for (let i = 0; i < pedestalMats.length; i++) {
      pedestalMats[i].emissive.setHex(i === selected ? 0x2f6fdb : 0x000000);
      pedestalMats[i].emissiveIntensity = i === selected ? 0.85 : 0;
    }
    info.set('detail', { text: detailFor(index) });
  }

  traits(phoenixIcon, { onPress: () => selectCity(0) });
  traits(londonIcon, { onPress: () => selectCity(1) });
  traits(chicagoIcon, { onPress: () => selectCity(2) });

  info.on('unit', 'click', () => {
    useC = !useC;
    renderTemps();
  });

  selectCity(0);

  return {
    root,
    update(time, delta) {
      const step = Math.min(delta || 0.016, 0.05);
      if (sunRays) sunRays.rotation.z = time * 0.35;
      sunMat.emissiveIntensity = 0.85 + Math.sin(time * 2.0) * 0.15;
      if (rainCloud) rainCloud.position.y = Math.sin(time * 1.4) * 0.0035;
      if (snowCloud) snowCloud.position.y = Math.sin(time * 1.1 + 1.3) * 0.0035;
      for (let i = 0; i < rainDrops.length; i++) {
        const d = rainDrops[i];
        const cycle = (time * 0.085 + d.phase) % 0.055;
        d.mesh.position.y = -0.026 - cycle;
        d.mesh.position.x = d.baseX;
      }
      for (let i = 0; i < snowFlakes.length; i++) {
        const f = snowFlakes[i];
        const cycle = (time * 0.04 + f.phase) % 0.06;
        f.mesh.position.y = -0.026 - cycle;
        f.mesh.position.x = f.baseX + Math.sin(time * 2.0 + f.phase * 4.0) * 0.004;
      }
      for (let i = 0; i < icons.length; i++) {
        if (isGrabbed(icons[i])) continue;
        const target = i === selected ? 1.14 : 1.0;
        iconScales[i] += (target - iconScales[i]) * Math.min(1, step * 10);
        icons[i].scale.setScalar(iconScales[i]);
      }
    },
  };
}

