      new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.3 })
    );
    puff.position.set(0, 0.11, 0);
    steamGroup.add(puff);
    puffs.push({ mesh: puff, phase: i * 0.25, drift: (i - 1.5) * 0.004 });
  }

  // Info card with price and material
  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .price { color: #ffd166; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .row { flex-direction: row; gap: 10px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #17665c; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Stoneware Coffee Mug</span>
      <span class="price">$18.50</span>
      <span class="body">Made of: glazed stoneware ceramic. Fired clay with a lead-free glaze, smooth inside for coffee.</span>
      <span class="body" id="detail">350 ml (12 oz). Dishwasher and microwave safe. Colour: Teal.</span>
      <span class="body" id="hint">Pinch the mug to pick it up. Poke it for a hot-coffee warning.</span>
      <div class="row">
        <button class="btn" id="colour"><span class="btn-text">Change colour</span></button>
        <button class="btn" id="steam"><span class="btn-text" id="steamLabel">Steam: On</span></button>
      </div>
    </div>`, { width: 0.34, position: [0.19, 0.21, 0], rotationY: -0.15 });
  root.add(info.object3D);

  const colours = [
    { hex: 0x17665c, text: '350 ml (12 oz). Dishwasher and microwave safe. Colour: Teal.' },
    { hex: 0xb5522e, text: '350 ml (12 oz). Dishwasher and microwave safe. Colour: Terracotta.' },
    { hex: 0x2f4a7a, text: '350 ml (12 oz). Dishwasher and microwave safe. Colour: Navy.' },
    { hex: 0xd9c9a3, text: '350 ml (12 oz). Dishwasher and microwave safe. Colour: Cream.' }
  ];
  let colourIndex = 0;
  info.on('colour', 'click', () => {
    colourIndex = (colourIndex + 1) % colours.length;
    glaze.color.setHex(colours[colourIndex].hex);
    info.set('detail', { text: colours[colourIndex].text });
  });

  let steamOn = true;
  info.on('steam', 'click', () => {
    steamOn = !steamOn;
    steamGroup.visible = steamOn;
    info.set('steamLabel', { text: steamOn ? 'Steam: On' : 'Steam: Off' });
  });

  traits(mug, {
    grab: true,
    onPress: () => {
      info.set('hint', { text: 'Careful - the coffee is hot. Hold the handle and keep the mug upright.' });
    }
  });

  return {
    root,
    update(time) {
      if (!steamGroup.visible || isGrabbed(mug)) return;
      for (let i = 0; i < puffs.length; i++) {
        const p = puffs[i];
        const t = (time * 0.28 + p.phase) % 1;
        p.mesh.position.y = 0.108 + t * 0.065;
        p.mesh.position.x = p.drift + Math.sin(time * 1.2 + p.phase * 6.283) * 0.004 * t;
        p.mesh.scale.setScalar(0.6 + t * 1.1);
        p.mesh.material.opacity = 0.32 * (1 - t);
      }
    }
  };
}

