      new THREE.Vector3(x, 0.055, 0),
      new THREE.Vector3(x + 0.008, 0.09, 0.006 * side),
      new THREE.Vector3(x - 0.006, 0.12, -0.004 * side),
      new THREE.Vector3(x + 0.004, 0.145, 0)
    ]);
    const wisp = new THREE.Mesh(new THREE.TubeGeometry(curve, 20, 0.0028, 8, false), steamMaterial);
    wisp.name = 'Steam Wisp';
    steam.add(wisp);
  }
  mug.add(steam);

  // A few coffee beans resting on the placemat.
  const beanGeometry = new THREE.SphereGeometry(0.011, 16, 12);
  const beanMaterial = new THREE.MeshStandardMaterial({ color: 0x4a2a15, roughness: 0.7, metalness: 0.0 });
  const beanData = [
    [-0.27, 0.01, 0.09, 0.4],
    [-0.08, 0.01, 0.085, -0.3],
    [-0.25, 0.01, -0.085, 0.8]
  ];
  for (let i = 0; i < beanData.length; i++) {
    const bean = new THREE.Mesh(beanGeometry, beanMaterial);
    bean.name = 'Coffee Bean';
    bean.position.set(beanData[i][0], beanData[i][1], beanData[i][2]);
    bean.scale.set(1, 0.55, 1.35);
    bean.rotation.y = beanData[i][3];
    root.add(bean);
  }

  // Product card with price and material.
  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1f2228;
              border-width: 2px; border-color: #3a3f48; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .subtitle { color: #9fd8cf; font-size: 22px; }
      .highlight { flex-direction: row; align-items: center; justify-content: space-between; gap: 12px;
                   padding-top: 12px; padding-bottom: 12px; padding-left: 16px; padding-right: 16px;
                   border-radius: 14px; background-color: #2a2e35; }
      .label { color: #c9ced8; font-size: 22px; }
      .price { color: #ffd166; font-size: 38px; font-weight: 700; }
      .body { color: #e6e9ee; font-size: 22px; }
      .status { color: #b8e6ff; font-size: 22px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px;
              border-radius: 12px; background-color: #3a404d; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      .row { flex-direction: row; gap: 10px; }
    </style>
    <div class="card">
      <span class="title">Stoneware Coffee Mug</span>
      <span class="subtitle">Glazed stoneware ceramic</span>
      <div class="highlight">
        <span class="label">Price</span>
        <span class="price">$18.50</span>
      </div>
      <span class="body">Made of: glazed stoneware ceramic, fired for strength with a smooth easy-clean glaze.</span>
      <span class="body">Capacity: 350 ml (12 oz). Dishwasher safe and microwave safe.</span>
      <span class="status" id="status">Pinch the mug to pick it up. Try holding it by the handle.</span>
      <button class="btn" id="buy"><span class="btn-text" id="buyText">Add to cart - $18.50</span></button>
      <div class="row">
        <button class="btn2" id="reset"><span class="btn-text">Reset mug</span></button>
        <button class="btn2" id="steamToggle"><span class="btn-text" id="steamText">Steam: On</span></button>
      </div>
    </div>`, { width: 0.34, position: [0.22, 0.2, 0.03], rotationY: -0.15 });
  root.add(info.object3D);

  const homePosition = mug.position.clone();
  const homeRotation = mug.rotation.clone();
  let cartCount = 0;
  let steamOn = true;

  info.on('buy', 'click', () => {
    cartCount += 1;
    const total = (cartCount * 18.5).toFixed(2);
    const noun = cartCount === 1 ? 'mug' : 'mugs';
    info.set('status', { text: `Added to cart. Total: $${total} for ${cartCount} ${noun}. Glazed stoneware, 350 ml.` });
    info.set('buyText', { text: 'Added - add another' });
  });

  info.on('reset', 'click', () => {
    if (!isGrabbed(mug)) {
      mug.position.copy(homePosition);
      mug.rotation.copy(homeRotation);
      info.set('status', { text: 'Mug reset to the saucer. Pinch it again to pick it up.' });
    }
  });

  info.on('steamToggle', 'click', () => {
    steamOn = !steamOn;
    steam.visible = steamOn;
    info.set('steamText', { text: steamOn ? 'Steam: On' : 'Steam: Off' });
    info.set('status', { text: steamOn ? 'Steam is on. The coffee is hot.' : 'Steam is off. The coffee is ready to drink.' });
  });

  traits(mug, { grab: true });

  return {
    root,
    update(time) {
      if (isGrabbed(mug)) return;
      steam.rotation.z = Math.sin(time * 0.7) * 0.06;
      steam.rotation.x = Math.cos(time * 0.55) * 0.03;
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
