        .city { color: #ffffff; font-size: 28px; font-weight: 700; text-align: center; }
        .temp { font-size: 42px; font-weight: 700; text-align: center; }
        .t0 { color: #ffd166; }
        .t1 { color: #8ec5ff; }
        .t2 { color: #c8f0ff; }
        .cond { color: #d7dbe2; font-size: 24px; font-weight: 700; text-align: center; }
        .meta { color: #aeb6c2; font-size: 22px; text-align: center; }
      </style>
      <div class="card" id="card">
        <span class="strip s${i}"></span>
        <span class="city">${city.name.toUpperCase()}</span>
        <span class="temp t${i}" id="temp">${city.tempC}</span>
        <span class="cond">${city.condition}</span>
        <span class="meta">Humidity ${city.humidity}% - Wind ${city.wind} km/h</span>
      </div>`, { width: 0.24, position: [xs[i], 0.26, -0.04], rotationY: rots[i] });
    root.add(panel.object3D);
    cardPanels.push(panel);
  }

  const detailPanel = ui(`
    <style>
      .bar { width: 540px; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1f2228; }
      .row { flex-direction: row; align-items: center; justify-content: space-between; gap: 12px; }
