      .question { color: #ffffff; font-size: 36px; font-weight: 700; text-align: center; }
      .feedback { color: #d7dbe2; font-size: 22px; text-align: center; height: 56px; }
      .row { display: flex; flex-direction: row; gap: 10px; justify-content: center; }
      .btn { width: 170px; height: 54px; border-radius: 12px; background-color: #2f3b52; border-width: 0px; border-color: #2f3b52; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
