        }
      },
    });
  }

  const UP = new THREE.Vector3(0, 1, 0);
  const tmpDir = new THREE.Vector3();
  let lastStatusKey = '';

  return {
    root,
    update(time, delta) {
      // Update bonds and bonded highlights. Atom positions are never animated here,
      // so a grabbed atom is never fought by the update.
      for (let i = 0; i < atoms.length; i++) atoms[i].bonded = false;

      let bondIndex = 0;
      for (let oi = 0; oi < oxygens.length; oi++) {
        const oAtom = oxygens[oi];
        const o = oAtom.mesh.position;
        for (let hi = 0; hi < hydrogens.length; hi++) {
          const hAtom = hydrogens[hi];
          const h = hAtom.mesh.position;
          const dx = h.x - o.x;
          const dy = h.y - o.y;
          const dz = h.z - o.z;
          const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
          if (dist < BOND_DIST && bondIndex < bonds.length) {
            const bond = bonds[bondIndex];
            bondIndex++;
            bond.visible = true;
            bond.position.set((o.x + h.x) / 2, (o.y + h.y) / 2, (o.z + h.z) / 2);
            tmpDir.set(dx, dy, dz).normalize();
            bond.quaternion.setFromUnitVectors(UP, tmpDir);
            bond.scale.set(1, dist, 1);
            oAtom.bonded = true;
            hAtom.bonded = true;
          }
        }
      }
      for (let i = bondIndex; i < bonds.length; i++) bonds[i].visible = false;

      for (let i = 0; i < atoms.length; i++) {
        const atom = atoms[i];
        atom.mat.emissiveIntensity = atom.bonded ? (atom.el === 'O' ? 1.0 : 0.6) : (atom.el === 'O' ? 0.35 : 0.15);
      }

      computeState();
      const key = stateType + ':' + (stateType === 'angle' ? Math.round(stateAngle) : 0);
      if (key !== lastStatusKey) {
        lastStatusKey = key;
        if (stateType === 'none') {
          info.set('status', { text: 'No bonds yet. Move a white H to a red O.', color: '#ffffff' });
        } else if (stateType === 'one') {
          info.set('status', { text: '1 bond formed. Add a second H to the same O.', color: '#ffd166' });
        } else if (stateType === 'good') {
          info.set('status', { text: 'Bent shape looks right. Press Check.', color: '#9ef0b0' });
        } else if (stateType === 'angle') {
          info.set('status', { text: 'Angle is ' + Math.round(stateAngle) + ' degrees. Make a bent shape near 104 degrees.', color: '#ffb4a2' });
        } else {
          info.set('status', { text: 'Too many H atoms on one O. Water has exactly 2.', color: '#ffb4a2' });
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const basketPos = new THREE.Vector3(0.22, 0, 0.02);

  const sphereGeo = new THREE.SphereGeometry(1, 24, 16);
  const cylGeo = new THREE.CylinderGeometry(1, 1, 1, 8);
  const circleGeo = new THREE.CircleGeometry(1, 24);

  const redMat = new THREE.MeshStandardMaterial({ color: 0xd92b2b, roughness: 0.35 });
  const orangeMat = new THREE.MeshStandardMaterial({ color: 0xf58a1f, roughness: 0.5 });
  const orangeDarkMat = new THREE.MeshStandardMaterial({ color: 0xc86a12, roughness: 0.6 });
  const bananaMat = new THREE.MeshStandardMaterial({ color: 0xf7d154, roughness: 0.5 });
  const greenMat = new THREE.MeshStandardMaterial({ color: 0x3f9e4d, roughness: 0.6 });
  const brownMat = new THREE.MeshStandardMaterial({ color: 0x6b4423, roughness: 0.8 });
  const basketMat = new THREE.MeshStandardMaterial({ color: 0x96603a, roughness: 0.9, side: THREE.DoubleSide });
  const basketDarkMat = new THREE.MeshStandardMaterial({ color: 0x5f3a20, roughness: 0.95 });
  const rimMat = new THREE.MeshStandardMaterial({ color: 0x7a4a28, roughness: 0.8, emissive: 0xff8c00, emissiveIntensity: 0.18 });

  function ball(parent, sx, sy, sz, material, x, y, z) {
    const m = new THREE.Mesh(sphereGeo, material);
    m.scale.set(sx, sy, sz);
    m.position.set(x, y, z);
    parent.add(m);
    return m;
  }

  function stem(parent, sx, sy, sz, material, x, y, z, rz) {
    const m = new THREE.Mesh(cylGeo, material);
    m.scale.set(sx, sy, sz);
    m.position.set(x, y, z);
    m.rotation.z = rz;
    parent.add(m);
    return m;
  }

  const mat = new THREE.Mesh(
    new THREE.BoxGeometry(0.76, 0.012, 0.38),
    new THREE.MeshStandardMaterial({ color: 0xcbb894, roughness: 0.9 })
  );
  mat.name = 'TableMat';
  mat.position.set(0, -0.006, 0.04);
  root.add(mat);

  function marker(x, z, color) {
    const m = new THREE.Mesh(circleGeo, new THREE.MeshStandardMaterial({ color, transparent: true, opacity: 0.4, roughness: 0.9 }));
    m.scale.set(0.055, 0.055, 1);
    m.rotation.x = -Math.PI / 2;
    m.position.set(x, 0.002, z);
    root.add(m);
  }
  marker(-0.30, 0.07, 0xe57373);
  marker(-0.19, 0.07, 0xffb74d);
  marker(-0.08, 0.07, 0xfff176);

  const basket = new THREE.Group();
  basket.name = 'Basket';
  basket.position.copy(basketPos);
  root.add(basket);

  const basketBottom = new THREE.Mesh(new THREE.CylinderGeometry(0.057, 0.05, 0.012, 24), basketMat);
  basketBottom.position.y = 0.006;
  basket.add(basketBottom);

  const basketSide = new THREE.Mesh(new THREE.CylinderGeometry(0.078, 0.057, 0.084, 24, 1, true), basketMat);
  basketSide.position.y = 0.052;
  basket.add(basketSide);

  const basketInner = new THREE.Mesh(new THREE.CircleGeometry(0.055, 24), basketDarkMat);
  basketInner.rotation.x = -Math.PI / 2;
  basketInner.position.y = 0.013;
  basket.add(basketInner);

  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.078, 0.009, 10, 32), rimMat);
  rim.rotation.x = Math.PI / 2;
  rim.position.y = 0.094;
  basket.add(rim);

  const band1 = new THREE.Mesh(new THREE.TorusGeometry(0.062, 0.0045, 8, 32), basketDarkMat);
  band1.rotation.x = Math.PI / 2;
  band1.position.y = 0.03;
  basket.add(band1);

  const band2 = new THREE.Mesh(new THREE.TorusGeometry(0.071, 0.0045, 8, 32), basketDarkMat);
  band2.rotation.x = Math.PI / 2;
  band2.position.y = 0.062;
  basket.add(band2);

  const slatGeo = new THREE.BoxGeometry(0.018, 0.078, 0.005);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    const slat = new THREE.Mesh(slatGeo, basketMat);
    slat.position.set(Math.cos(a) * 0.067, 0.052, Math.sin(a) * 0.067);
    slat.rotation.y = -a + Math.PI / 2;
    basket.add(slat);
  }

  for (const side of [-1, 1]) {
    const handle = new THREE.Mesh(new THREE.TorusGeometry(0.032, 0.006, 8, 20, Math.PI), basketDarkMat);
    handle.position.set(side * 0.076, 0.092, 0);
    handle.rotation.y = Math.PI / 2;
    basket.add(handle);
  }

  const apple = new THREE.Group();
  apple.name = 'Apple';
  apple.position.set(-0.30, 0.035, 0.07);
  root.add(apple);
  ball(apple, 0.038, 0.035, 0.038, redMat, 0, 0, 0);
  stem(apple, 0.0035, 0.022, 0.0035, brownMat, 0.004, 0.04, 0, -0.18);
  const leaf = ball(apple, 0.022, 0.007, 0.011, greenMat, 0.019, 0.046, 0);
  leaf.rotation.z = -0.5;

  const orange = new THREE.Group();
  orange.name = 'Orange';
  orange.position.set(-0.19, 0.037, 0.07);
  root.add(orange);
  ball(orange, 0.037, 0.037, 0.037, orangeMat, 0, 0, 0);
  stem(orange, 0.003, 0.014, 0.003, brownMat, 0, 0.04, 0, 0.1);
  ball(orange, 0.013, 0.006, 0.013, orangeDarkMat, 0, 0.035, 0);

  const banana = new THREE.Group();
  banana.name = 'Banana';
  banana.position.set(-0.08, 0.016, 0.07);
  banana.rotation.y = -0.35;
  root.add(banana);
  const bananaMesh = new THREE.Mesh(new THREE.TorusGeometry(0.038, 0.015, 12, 24, 2.25), bananaMat);
  bananaMesh.rotation.x = Math.PI / 2;
  banana.add(bananaMesh);
  ball(banana, 0.015, 0.015, 0.015, bananaMat, 0.038, 0, 0);
  ball(banana, 0.015, 0.015, 0.015, bananaMat, -0.024, 0, 0.030);
  stem(banana, 0.006, 0.02, 0.006, brownMat, 0.043, 0.008, 0, 0.9);

  const fruits = [
    { group: apple, name: 'Apple', price: 120, statusId: 'appleStatus', home: new THREE.Vector3(-0.30, 0.035, 0.07), slot: new THREE.Vector3(0.19, 0.066, -0.01), restY: 0.035, homeRotY: 0, slotRotY: 0.5, inBasket: false },
    { group: orange, name: 'Orange', price: 90, statusId: 'orangeStatus', home: new THREE.Vector3(-0.19, 0.037, 0.07), slot: new THREE.Vector3(0.25, 0.066, 0.04), restY: 0.037, homeRotY: 0, slotRotY: -0.4, inBasket: false },
    { group: banana, name: 'Banana', price: 150, statusId: 'bananaStatus', home: new THREE.Vector3(-0.08, 0.016, 0.07), slot: new THREE.Vector3(0.22, 0.102, 0.015), restY: 0.016, homeRotY: -0.35, slotRotY: 0.3, inBasket: false }
  ];

  const info = ui(`
    <style>
      .card { width: 540px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; border-width: 2px; border-color: #464c57; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; text-align: center; }
      .sub { color: #c8d0dc; font-size: 22px; text-align: center; }
      .status { color: #e8ecf2; font-size: 23px; padding-top: 7px; padding-bottom: 7px; padding-left: 14px; padding-right: 14px; border-radius: 10px; background-color: #2a2e35; }
      .total { color: #ffd166; font-size: 27px; font-weight: 700; text-align: center; padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; border-radius: 10px; background-color: #3a330f; }
      .msg { color: #9fd0ff; font-size: 21px; text-align: center; }
      .btn { padding-top: 11px; padding-bottom: 11px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2f9e44; border-width: 2px; border-color: #37c24f; }
      .btn-text { color: #ffffff; font-size: 23px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Fruit Basket Shop</span>
      <span class="sub">Drop fruit in the basket to add its price.</span>
      <span class="status" id="appleStatus">Apple: on table ($1.20)</span>
      <span class="status" id="orangeStatus">Orange: on table ($0.90)</span>
      <span class="status" id="bananaStatus">Banana: on table ($1.50)</span>
      <span class="total" id="total">Basket total: $0.00 (0 of 3)</span>
      <span class="msg" id="message">Pinch a fruit, move it over the basket, and let go.</span>
      <button class="btn" id="reset"><span class="btn-text">Empty basket and reset</span></button>
    </div>`, { width: 0.42, position: [0, 0.33, -0.15], rotationY: 0 });
  root.add(info.object3D);

  function money(cents) {
    return '$' + (cents / 100).toFixed(2);
  }

  function basketTotal() {
    let total = 0;
    for (const f of fruits) {
      if (f.inBasket) total += f.price;
    }
    return total;
  }

  function basketCount() {
    let count = 0;
    for (const f of fruits) {
      if (f.inBasket) count += 1;
    }
    return count;
  }

  function updatePanel(customMessage) {
    const total = basketTotal();
    const count = basketCount();
    for (const f of fruits) {
      info.set(f.statusId, {
        text: f.name + ': ' + (f.inBasket ? 'in basket  ' : 'on table  ') + '(' + money(f.price) + ')',
        color: f.inBasket ? '#b2f2bb' : '#e8ecf2',
        backgroundColor: f.inBasket ? '#1f3d2b' : '#2a2e35'
      });
    }
    info.set('total', { text: 'Basket total: ' + money(total) + ' (' + count + ' of 3)' });
    let message = customMessage;
    if (!message) {
      if (count === 0) message = 'Pinch a fruit, move it over the basket, and let go.';
      else if (count === 3) message = 'Basket full. Press Empty basket to shop again.';
      else if (count === 2) message = 'Almost full - one more fruit to go.';
      else message = 'Good - drop another fruit in the basket.';
    }
    info.set('message', { text: message });
  }

  info.on('reset', 'click', () => {
    for (const f of fruits) {
      f.inBasket = false;
      f.group.position.copy(f.home);
      f.group.rotation.set(0, f.homeRotY, 0);
    }
    updatePanel('Basket emptied. Pinch a fruit to start again.');
  });

  for (const f of fruits) {
    traits(f.group, { grab: true });
  }
  traits(basket, {
    onPress: () => info.set('message', { text: 'Basket total is ' + money(basketTotal()) + ' for ' + basketCount() + ' item(s).' })
  });

  updatePanel();

  return {
    root,
    update(time, delta) {
      const dt = delta && delta > 0 ? delta : 0.016;
      const settle = Math.min(1, dt * 7);
      const move = Math.min(1, dt * 9);
      let hovering = false;

      for (const f of fruits) {
        const dx = f.group.position.x - basketPos.x;
        const dz = f.group.position.z - basketPos.z;
        const distSq = dx * dx + dz * dz;

        if (isGrabbed(f.group)) {
          if (f.inBasket) {
            f.inBasket = false;
            updatePanel();
          }
          if (distSq < 0.085 * 0.085) hovering = true;
          continue;
        }

        if (f.inBasket) {
          f.group.position.lerp(f.slot, move);
          f.group.rotation.y += (f.slotRotY - f.group.rotation.y) * move;
          continue;
        }

        if (distSq < 0.085 * 0.085 && f.group.position.y < 0.17) {
          f.inBasket = true;
          updatePanel();
          continue;
        }

        f.group.position.y += (f.restY - f.group.position.y) * settle;
        f.group.position.x = THREE.MathUtils.clamp(f.group.position.x, -0.36, 0.36);
        f.group.position.z = THREE.MathUtils.clamp(f.group.position.z, -0.14, 0.20);
      }

      rimMat.emissiveIntensity = hovering ? 0.9 : 0.18;
    }
  };
}
